window.CHAPTER_DATA = {"1":"<section class=\"chapter-section\" id=\"ch1\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">1</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (गद्य खंड) — पाठ 1</div>\n      <h2>नेताजी का चश्मा</h2>\n      <p>स्वयं प्रकाश | कहानी — देशभक्ति, नागरिक कर्तव्य और कैप्टन चश्मेवाले का राष्ट्रप्रेम | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch1-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">सेनानी न होते हुए भी चश्मेवाले को लोग 'कैप्टन' क्यों कहते थे?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>चश्मेवाला न तो कोई फौजी था और न ही सुभाष चंद्र बोस की 'आज़ाद हिंद फ़ौज' का भूतपूर्व सिपाही। फिर भी कस्बे के लोग उसे आदर और व्यंग्य के मिले-जुले भाव से 'कैप्टन' कहते थे, जिसके प्रमुख कारण निम्नलिखित हैं:</p>\n          <ul>\n            <li><strong>प्रगाढ़ देशभक्ति व राष्ट्रप्रेम:</strong> चश्मेवाले के हृदय में देश के शहीदों और स्वतंत्रता सेनानियों के प्रति अपार श्रद्धा थी। नेताजी की बिना चश्मे वाली अधूरी मूर्ति उसे कचोटती थी।</li>\n            <li><strong>सक्रिय नागरिक निष्ठा:</strong> वह अत्यंत निर्धन और शारीरिक रूप से अपंग (लँगड़ा) फेरीवाला था, फिर भी अपने सीमित संसाधनों में से नेताजी की मूर्ति पर अपनी ओर से नियमित चश्मा लगाता था।</li>\n            <li><strong>सेनानी जैसी मानसिक भावना:</strong> सेनानी की वर्दी न पहनते हुए भी उसके विचार व समर्पण एक सच्चे सिपाही जैसे थे, इसलिए कस्बे वाले उसे 'कैप्टन' कहकर पुकारते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वतंत्रता सेनानियों व नेताजी के प्रति अगाध श्रद्धा का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गरीबी व अपंगता के बावजूद नियमित चश्मा लगाने की निष्ठा</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक भाषा एवं शब्द-संयोजन</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch1-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">हालदार साहब ने ड्राइवर को पहले चौराहे पर गाड़ी रोकने के लिए मना किया था, लेकिन बाद में तुरंत रोकने को कहा— (क) हालदार साहब पहले मायूस क्यों हो गए थे? (ख) मूर्ति पर सरकंडे का चश्मा क्या उम्मीद जगाता है? (ग) हालदार साहब इतनी-सी बात पर भावुक क्यों हो उठे?</div>\n      <div class=\"q-marks\">5 अंक (100-120 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>(क) हालदार साहब की मायूसी का कारण:</strong> हालदार साहब को पता चला था कि देशभक्त कैप्टन चश्मेवाले की मृत्यु हो चुकी है। वे मायूस थे कि अब कस्बे के चौराहे पर नेताजी की मूर्ति तो होगी, किंतु उसकी आँखों पर चश्मा लगाने वाला कोई नहीं होगा, क्योंकि मास्टर जी बनाना भूल गए और कैप्टन अब रहा नहीं।</p>\n          <p><strong>(ख) सरकंडे के चश्मे से जागने वाली उम्मीद:</strong> सरकंडा घास की तीली से बना एक छोटा-सा खिलौना चश्मा था, जिसे प्रायः छोटे बच्चे खेल-खेल में बनाते हैं। यह चश्मा इस पावन सत्य को उजागर करता है कि देशभक्ति किसी एक व्यक्ति तक सीमित नहीं है, बल्कि देश की नई पीढ़ी (बच्चों) के नन्हें दिलों में भी राष्ट्रप्रेम और शहीदों के प्रति सम्मान जीवित है। देश का भविष्य सुरक्षित हाथों में है।</p>\n          <p><strong>(ग) हालदार साहब के भावुक होने का कारण:</strong> हालदार साहब ने जब देखा कि साधनहीन बच्चों ने अपनी बाल-सुलभ भावना से नेताजी की आँखों पर सरकंडे का चश्मा पहना रखा है, तो उनकी निराशा पल भर में आशा में बदल गई। इस पवित्र राष्ट्रभाव को देखकर उनकी आँखें भर आईं और वे श्रद्धा से अभिभूत हो उठे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): कैप्टन की मृत्यु व मूर्ति के चश्माविहीन होने की चिंता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): भावी पीढ़ी में राष्ट्रप्रेम व देश के सुरक्षित भविष्य की आशा</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ग): बच्चों की निष्ठा व भावुक संवेदनशीलता का प्रभाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch1-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">आशय स्पष्ट कीजिए— \"बार-बार सोचते, क्या होगा उस कौम का जो अपने देश की खातिर घर-गृहस्थी-जवानी-जिंदगी सब कुछ होम कर देने वालों पर भी हँसती है और अपने लिए बिकने के मौके ढूँढ़ती है?\"</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>भावार्थ / आशय:</strong> इस पंक्ति के माध्यम से लेखक ने समाज में बढ़ती स्वार्थपरता, संवेदनहीनता और देशभक्ति के घटते सम्मान पर गहरा व्यंग्य व क्षोभ प्रकट किया है:</p>\n          <ul>\n            <li>जिन अमर बलिदानियों ने देश की स्वतंत्रता और मान-मर्यादा के लिए अपना सर्वस्व (परिवार, यौवन और जीवन) न्योछावर कर दिया, आज का स्वार्थी समाज उनका आदर करने के बजाय उनका उपहास उड़ाता है (जैसे पानवाले द्वारा कैप्टन को 'पागल' कहना)।</li>\n            <li>जो जाति या राष्ट्र अपने शहीदों और सच्चे देशभक्तों का सम्मान नहीं करता, बल्कि निजी लाभ के लिए अपने सिद्धांतों और जमीर को बेचने को तत्पर रहता है, उसका पतन निश्चित है। ऐसी कौम कभी स्वाभिमानी और सुरक्षित नहीं रह सकती।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शहीदों के त्याग के प्रति समाज के उपहास व संवेदनहीनता पर प्रहार</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वार्थपरक आचरण व जाति के भावी पतन की चेतावनी</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch1-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">पानवाले का एक रेखाचित्र प्रस्तुत कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कहानी में पानवाले का चरित्र अत्यंत सजीव, यथार्थ और रोचक ढंग से चित्रित किया गया है:</p>\n          <ul>\n            <li><strong>शारीरिक स्वरूप:</strong> पानवाला एक काला, मोटा और खुशमिज़ाज व्यक्ति था। उसके मुँह में हमेशा पान ठुँसा रहता था, जिसके कारण उसकी बत्तीसी लाल-काली हो गई थी। जब वह हँसता था, तो उसकी भारी तोंद थिरकती थी।</li>\n            <li><strong>स्वभाव:</strong> वह बातूनी, मज़ाकिया और व्यंग्य करने में माहिर था। कस्बे की हर गतिविधि और गपशप की उसे पूरी जानकारी रहती थी।</li>\n            <li><strong>छिपी संवेदनशीलता:</strong> ऊपरी तौर पर भले ही उसने कैप्टन को 'पागल' कहकर उसका मज़ाक उड़ाया था, परंतु अंततः कैप्टन की मृत्यु पर वह भी उदास हो गया और आँखें पोंछते हुए भावुक हो उठा, जिससे सिद्ध होता है कि वह भीतर से सहृदय था।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शारीरिक बनावट व बोलचाल की शैली का यथार्थ चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यवहार के अंतर्विरोध (मज़ाक व अंतिम संवेदनशीलता) का अंकन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch1-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">\"वो लँगड़ा क्या जाएगा फ़ौज में। पागल है पागल!\"— कैप्टन के प्रति पानवाले की इस टिप्पणी पर अपनी प्रतिक्रिया लिखिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पानवाले द्वारा कैप्टन के प्रति की गई यह टिप्पणी अत्यंत निंदनीय, संवेदनहीन और गैर-ज़िम्मेदाराना थी:</p>\n          <ul>\n            <li><strong>देशभक्ति का अपमान:</strong> कैप्टन शारीरिक रूप से दिव्यांग और विपन्न अवश्य था, किंतु उसका देशप्रेम और शहीदों के प्रति सम्मान समूचे कस्बे में सबसे प्रखर था। उसके इस पावन संकल्प को 'पागलपन' कहना देशभक्ति का घोर अनादर है।</li>\n            <li><strong>दिव्यांगता का उपहास अनुचित:</strong> किसी व्यक्ति की शारीरिक अशक्तता का उपहास उड़ाना मानवीय मूल्यों के विरुद्ध है। देश की सेवा केवल सीमा पर बंदूक थामकर ही नहीं होती, बल्कि नागरिक कर्तव्यों का निष्ठापूर्वक पालन करना भी सच्ची देशसेवा है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">टिप्पणी की संवेदनहीनता व उपहास का स्पष्ट विरोध</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नागरिक कर्तव्यों एवं आत्मिक देशभक्ति की महत्ता का प्रतिपादन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता आधारित प्रश्न (Competency-Based Questions / CBQs)</span>\n      <span class=\"cbq-badge\">CBSE Board NEP 2020</span>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> कैप्टन चश्मेवाले का राष्ट्रप्रेम किसी वर्दीधारी सैनिक से कम नहीं था।<br>\n        <strong>कारण (R):</strong> वह अपनी गरीबी और शारीरिक दिव्यांगता के बावजूद नेताजी की मूर्ति को कभी चश्माविहीन नहीं रहने देता था।<br>\n        <strong>विकल्प:</strong><br>\n        (क) अभिकथन (A) और कारण (R) दोनों सही हैं तथा कारण (R), अभिकथन (A) की सही व्याख्या करता है।<br>\n        (ख) अभिकथन (A) और कारण (R) दोनों सही हैं, परंतु कारण (R), अभिकथन की सही व्याख्या नहीं करता।<br>\n        (ग) अभिकथन (A) सही है, परंतु कारण (R) गलत है।<br>\n        (घ) अभिकथन (A) गलत है, परंतु कारण (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> कैप्टन के पास सैन्य साधन नहीं थे, परंतु उसकी राष्ट्रभक्ति कर्म में प्रकट होती थी। उसने अपने सामर्थ्य से नेताजी की अधूरी मूर्ति को चश्मा देकर देशप्रेम की मिसाल पेश की, अतः कारण (R) सीधे तौर पर अभिकथन (A) की पुष्टि करता है।\n      </div>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 2: केस-आधारित प्रश्न (Case-Based Question)</div>\n      <div class=\"cbq-question\">\n        \"देशभक्ति केवल युद्धभूमि में प्राण न्योछावर करने का नाम नहीं है, अपितु दैनिक जीवन में राष्ट्रीय प्रतीकों का सम्मान करना भी देशभक्ति है।\" 'नेताजी का चश्मा' कहानी के आधार पर स्पष्ट कीजिए कि आम नागरिक देश निर्माण में किस प्रकार योगदान दे सकते हैं?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        कहानी यह अमर संदेश देती है कि देश सीमाओं से घिरे भू-भाग का नाम नहीं है, बल्कि वहाँ रहने वाले नागरिकों, प्रकृति, संस्कृति और राष्ट्रीय प्रतीकों से बनता है। आम नागरिक निम्नलिखित तरीकों से देशसेवा कर सकते हैं:<br>\n        1. <strong>राष्ट्रीय स्मारकों व प्रतीकों का आदर:</strong> महापुरुषों की प्रतिमाओं, तिरंगे और सार्वजनिक संपत्तियों की सुरक्षा व सम्मान करना।<br>\n        2. <strong>स्वच्छता व पर्यावरण संरक्षण:</strong> अपने आसपास के परिवेश को स्वच्छ रखना, जल-विद्युत की बचत करना।<br>\n        3. <strong>कर्तव्यनिष्ठा:</strong> अपने कार्य (पढ़ाई, व्यवसाय, नौकरी) को ईमानदारी से पूर्ण करना ताकि राष्ट्र समृद्ध बन सके।\n      </div>\n    </div>\n  </div>\n</section>","2":"<section class=\"chapter-section\" id=\"ch2\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">2</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (गद्य खंड) — पाठ 2</div>\n      <h2>बालगोबिन भगत</h2>\n      <p>रामवृक्ष बेनीपुरी | रेखाचित्र — कबीरपंथी संत, कर्मयोग, आडंबर-विरोध और सामाजिक सुधार | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch2-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">खेतीबारी से जुड़े गृहस्थ बालगोबिन भगत अपनी किन चारित्रिक विशेषताओं के कारण 'साधु' कहलाते थे?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बालगोबिन भगत बाह्य वेशभूषा या संन्यास के आडंबरों से नहीं, बल्कि अपने शुद्ध आचरण और उदात्त मानवीय गुणों के कारण 'साधु' थे:</p>\n          <ul>\n            <li><strong>सत्यवादी और निष्कपट आचरण:</strong> वे कभी झूठ नहीं बोलते थे और सभी के साथ खरा व्यवहार रखते थे। किसी से व्यर्थ झगड़ा नहीं करते थे।</li>\n            <li><strong>अपरिग्रह और ईमानदारी:</strong> वे किसी की वस्तु को बिना पूछे हाथ तक नहीं लगाते थे और न ही उसका व्यवहार में उपयोग करते थे।</li>\n            <li><strong>कबीर के प्रति अटूट निष्ठा:</strong> वे कबीर को 'साहब' मानते थे। अपने खेत में जो कुछ भी अनाज पैदा होता, उसे सिर पर लादकर पहले कबीरपंथी मठ ले जाते और वहाँ से प्रसाद रूप में जो बचता, उसी से गृहस्थी चलाते थे।</li>\n            <li><strong>राग-द्वेष से मुक्ति:</strong> वे सुख-दुख, लाभ-हानि में समभाव रहते थे तथा मृत्यु को परमात्मा से आत्मा का मिलन मानकर आनंद मनाते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सत्यवादिता, ईमानदारी और अपरिग्रह का स्पष्ट उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कबीर के प्रति समर्पण व सात्विक जीवन-शैली</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch2-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">भगत की पुत्रवधू उन्हें अकेले क्यों नहीं छोड़ना चाहती थी?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>भगत की पुत्रवधू अत्यंत सुशील, समझदार और संवेदनशील स्त्री थी। वह निम्नलिखित मानवीय कारणों से अपने वृद्ध ससुर को अकेला नहीं छोड़ना चाहती थी:</p>\n          <ul>\n            <li><strong>वृद्धावस्था और एकाकीपन की चिंता:</strong> भगत के इकलौते पुत्र की मृत्यु के बाद घर में उनकी देखभाल करने वाला कोई दूसरा नहीं बचा था।</li>\n            <li><strong>भोजन व स्वास्थ्य की फ़िक्र:</strong> भगत स्वयं कभी किसी से सेवा नहीं लेते थे। पुत्रवधू को चिंता थी कि यदि वे बीमार पड़ गए, तो उन्हें एक घूँट पानी देने वाला और समय पर भोजन पकाने वाला कोई नहीं रहेगा।</li>\n            <li><strong>सच्ची सेवा-भावना:</strong> वह अपने सुख और पुनर्जन्म के बजाय वृद्ध ससुर की सेवा को अपना परम धर्म मानती थी।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भगत के बुढ़ापे, एकाकीपन और बीमारी में सेवा की चिंता</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पुत्रवधू के निःस्वार्थ कर्तव्यबोध व पारिवारिक निष्ठा का अंकन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch2-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">भगत ने अपने बेटे की मृत्यु पर अपनी भावनाएँ किस तरह व्यक्त कीं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>इकलौते बेटे की मृत्यु पर भगत ने सामान्य सांसारिक लोगों की भाँति रोना-धोना या विलाप नहीं किया, बल्कि उनका व्यवहार अत्यंत दार्शनिक और अलौकिक था:</p>\n          <ul>\n            <li><strong>शव का सम्मान:</strong> उन्होंने बेटे के मृत शरीर को एक सफेद चादर से ढँक दिया, उस पर कुछ फूल और तुलसी दल बिखेर दिए और सिरहाने एक चिराग जला दिया।</li>\n            <li><strong>भक्ति गीतों का गायन:</strong> वे खंजड़ी बजाते हुए अपने उसी पुराने तन्मय स्वर में कबीर के पदों को गाने लगे।</li>\n            <li><strong>पुत्रवधू को सांत्वना व उत्सव मनाने की सीख:</strong> उन्होंने रोती हुई पुत्रवधू को समझाया कि यह शोक का नहीं, अपितु आनंद और उत्सव का अवसर है, क्योंकि आत्मा रूपी विरहिणी अपने परम प्रियतम परमात्मा से मिलने चली गई है। इससे बड़ा आनंद और क्या हो सकता है!</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विलाप न करके खंजड़ी बजाकर भजन गाने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आत्मा और परमात्मा के मिलन के दार्शनिक दृष्टिकोण का निरूपण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch2-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">भगत के व्यक्तित्व और उनकी वेशभूषा का अपने शब्दों में चित्र प्रस्तुत कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>शारीरिक स्वरूप व वेशभूषा:</strong></p>\n          <ul>\n            <li>बालगोबिन भगत साठ से ऊपर की उम्र के, मँझोले कद के गोरे-चिट्टे आदमी थे। उनके बाल पक चुके थे, लंबी दाढ़ी-जटाएँ नहीं थीं, किंतु चेहरा हमेशा श्वेत बालों से जगमगाता रहता था।</li>\n            <li>कपड़े बहुत कम पहनते थे—कमर में एक लँगोटी और सिर पर कबीरपंथियों की-सी कनफटी टोपी। जाड़े में काली कमली ओढ़ लेते थे।</li>\n            <li>माथे पर हमेशा रामानंदी चंदन का तिलक चमकता था, जो नाक के छोर से ऊपर की ओर उठता था और गले में तुलसी की जड़ों की बेडौल माला बँधी रहती थी।</li>\n            <li>हाथ में खंजड़ी लिए वे खेतों में रोपनी करते हुए स्वर-तरंग बिखेरते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शारीरिक बनावट, आयु व श्वेत केश का अंकन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कनफटी टोपी, लँगोटी, चंदन तिलक व तुलसी माला का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch2-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">बालगोबिन भगत की दिनचर्या लोगों के अचरज का कारण क्यों थी?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>भगत की दिनचर्या में अटूट नियमबद्धता और कठोर साधना थी, जो लोगों को विस्मित करती थी:</p>\n          <ul>\n            <li><strong>कड़कड़ाती ठंड में प्रभाती:</strong> जाड़े की हाड़ कँपाने वाली ठंड में भी वे भोर में तारे टिमटिमाते ही दो मील दूर नदी-स्नान के लिए जाते और लौटकर पोखर के ऊँचे भिंडे पर खंजड़ी बजाते हुए प्रभाती गाते थे।</li>\n            <li><strong>जीवन के अंतिम क्षण तक नियम-निष्ठा:</strong> वृद्धावस्था और बीमारी में भी उन्होंने अपने दोनों समय के स्नान-ध्यान, खेत की रखवाली और प्रभाती के नियमों को कभी नहीं छोड़ा। लोगों के मना करने पर भी वे अपनी साधना से विचलित नहीं हुए।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भोर में नदी स्नान व खंजड़ी बजाकर प्रभाती गाने की नियमितता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कठोर सर्दी व बीमारी में भी अटूट साधना और नियम पालन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता आधारित प्रश्न (Competency-Based Questions / CBQs)</span>\n      <span class=\"cbq-badge\">CBSE Board NEP 2020</span>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: सामाजिक सुधार एवं मूल्य-बोध</div>\n      <div class=\"cbq-question\">\n        बालगोबिन भगत ने पुत्र की मृत्यु के उपरांत अपनी पतोहू के पुनर्विवाह का आदेश देकर तत्कालीन रूढ़िवादी समाज को क्या संदेश दिया?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        तत्कालीन समाज में विधवा-विवाह वर्जित था और विधवा स्त्री को नारकीय व उपेक्षित जीवन व्यतीत करना पड़ता था। भगत ने परंपरावादी रूढ़ियों को तोड़ते हुए पतोहू के भाई को बुलाकर उसका दूसरा विवाह कराने का दृढ़ आदेश दिया। उन्होंने यह क्रांतिकारी संदेश दिया कि धर्म का सच्चा स्वरूप मानवता, नारी-सहानुभूति और उसके सुखमय भविष्य में है, न कि संकीर्ण सामाजिक कुरीतियों में।\n      </div>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 2: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> बालगोबिन भगत संन्यासी न होकर भी सच्चे साधु थे।<br>\n        <strong>कारण (R):</strong> साधुता बाहरी वेशभूषा या परिवार त्यागने से नहीं, बल्कि आंतरिक सात्विकता और पवित्र आचरण से सिद्ध होती है।<br>\n        <strong>विकल्प:</strong> (क) A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है। (ख) A और R दोनों सत्य हैं, परंतु R सही व्याख्या नहीं है। (ग) A सत्य है, R असत्य है। (घ) A असत्य है, R सत्य है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> भगत खेती-गृहस्थी करते हुए भी निष्काम कर्मयोगी और पवित्र आचरण के धनी थे, जो सिद्ध करता है कि संन्यास मन की वृत्ति है, बाह्य आवरण नहीं।\n      </div>\n    </div>\n  </div>\n</section>","3":"<section class=\"chapter-section\" id=\"ch3\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">3</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (गद्य खंड) — पाठ 3</div>\n      <h2>लखनवी अंदाज़</h2>\n      <p>यशपाल | व्यंग्य — पतनशील सामंती वर्ग, दिखावटी जीवन-शैली और नई कहानी पर कटाक्ष | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch3-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">लेखक को नवाब साहब के किन हाव-भावों से महसूस हुआ कि वे उनसे बातचीत करने के लिए तनिक भी उत्सुक नहीं हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>जब लेखक सेकंड क्लास के डिब्बे में अचानक चढ़े, तो उन्होंने नवाब साहब के व्यवहार में निम्नलिखित उपेक्षापूर्ण हाव-भाव देखे:</p>\n          <ul>\n            <li><strong>एकांत चिंतन में विघ्न का असंतोष:</strong> नवाब साहब की आँखों में लेखक के सहसा आ जाने से असुविधा और संकोच का भाव स्पष्ट दिखाई दिया।</li>\n            <li><strong>उपेक्षा व अनिच्छा:</strong> उन्होंने लेखक की संगति के प्रति कोई उत्साह नहीं दिखाया और न ही उनका अभिवादन किया।</li>\n            <li><strong>खिड़की से बाहर देखना:</strong> उन्होंने लेखक से नज़रें चुराकर खिड़की के बाहर देखना शुरू कर दिया, जिससे लेखक को स्पष्ट हो गया कि वे बातचीत के बिल्कुल अनिच्छुक हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आँखों में असंतोष व संकोच का भाव प्रकट होना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नज़रें चुराकर खिड़की के बाहर देखने की उपेक्षापूर्ण मुद्रा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch3-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">नवाब साहब ने बहुत ही यत्न से खीरा काटा, नमक-मिर्च बुरका, अंततः सूँघकर ही खिड़की से बाहर फेंक दिया। उन्होंने ऐसा क्यों किया होगा? उनका ऐसा करना उनके कैसे स्वभाव को इंगित करता है?</div>\n      <div class=\"q-marks\">4 अंक (60-70 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>खीरा फेंकने का कारण:</strong> नवाब साहब लेखक के सामने अपनी कल्पित नवाबी नफासत, खानदानी रईसी और विशिष्टता (एलीट स्टेटस) का दिखावा करना चाहते थे। खीरे जैसी साधारण वस्तु को खाना वे अपनी शान के खिलाफ समझते थे, इसलिए उन्होंने प्रत्येक फाँक को केवल सूँघा और तृप्ति की डकार लेते हुए खिड़की से बाहर फेंक दिया।</p>\n          <p><strong>स्वभाव की विशेषताएँ:</strong></p>\n          <ul>\n            <li><strong>दिखावटीपन और कृत्रिमता:</strong> वे यथार्थ से दूर झूठे प्रदर्शन और दंभपूर्ण व्यवहार में जीते थे।</li>\n            <li><strong>सामंती खोखलापन:</strong> उनका यह कृत्य पतनशील सामंती संस्कृति के उस अहंकार को दर्शाता है, जिसमें वास्तविकता कुछ नहीं होती परंतु केवल शिष्टाचार और नज़ाकत का स्वांग रचा जाता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नवाबी नफासत व झूठी रईसी के प्रदर्शन का कारण स्पष्ट करना</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दिखावटीपन, दंभ और सामंती खोखलेपन का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch3-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">बिना विचार, घटना और पात्रों के भी क्या कहानी लिखी जा सकती है? यशपाल के इस विचार से आप कहाँ तक सहमत हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>हम लेखक यशपाल के इस व्यंग्यात्मक निष्कर्ष से पूर्णतः सहमत हैं:</p>\n          <ul>\n            <li>लेखक ने व्यंग्य करते हुए कहा है कि यदि खीरे को बिना खाए केवल सूँघने मात्र से पेट भर सकता है और डकार आ सकती है, तो बिना विचार, बिना कथ्य (घटना) और बिना पात्रों के भी कहानी लिखी जा सकती है।</li>\n            <li>परंतु वास्तविकता यह है कि कहानी की रचना के लिए एक केंद्रीय विचार (कथ्य), घटनाओं का प्रवाह और सजीव पात्र अनिवार्य तत्व हैं। इनके बिना कोई भी सार्थक रचना संभव नहीं है। लेखक ने तत्कालीन 'नई कहानी' के कुछ लेखकों के निराधार प्रयोगवाद पर यह तीखा कटाक्ष किया है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यंग्यात्मक संदर्भ (सूँघने से पेट भरने का साम्य) स्पष्ट करना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कहानी के मूल तत्वों (कथ्य, घटना, पात्र) की अनिवार्यता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch3-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">आप इस निबंध को और क्या नाम देना चाहेंगे? कारण सहित उत्तर दीजिए।</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>इस व्यंग्य रचना के लिए अन्य उपयुक्त शीर्षक निम्नलिखित हो सकते हैं:</p>\n          <ul>\n            <li><strong>'दिखावे की संस्कृति'</strong> अथवा <strong>'झूठी शान'</strong>: क्योंकि संपूर्ण पाठ में नवाब साहब की बनावटी जीवन-शैली और वास्तविकता से कटे थोथे अहंकार का उद्घाटन किया गया है।</li>\n            <li><strong>'नवाबी नफासत'</strong>: क्योंकि यह शीर्षक लखनऊ के सामंती तौर-तरीकों और उनकी कृत्रिम नज़ाकत पर सटीक चोट करता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उपयुक्त शीर्षक का सुझाव और तार्किक औचित्य</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता आधारित प्रश्न (Competency-Based Questions / CBQs)</span>\n      <span class=\"cbq-badge\">CBSE Board NEP 2020</span>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: यथार्थ बनाम दिखावा (Reality vs Pretense)</div>\n      <div class=\"cbq-question\">\n        वर्तमान समाज में भी 'लखनवी अंदाज़' जैसी दिखावटी प्रवृत्ति के उदाहरण देखने को मिलते हैं। आज के संदर्भ में दिखावे की संस्कृति के दुष्प्रभावों पर प्रकाश डालिए।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        आज के उपभोक्तावादी युग में सोशल मीडिया और भौतिकवादी जीवन में दिखावे की संस्कृति चरम पर है। लोग अपनी आर्थिक क्षमता से बढ़कर दिखावे के लिए ब्रांडेड वस्तुएँ, भव्य आयोजन और बनावटी जीवनशैली अपनाते हैं। इसके गंभीर दुष्प्रभाव हैं—मानसिक तनाव, कर्ज का बोझ, रिश्तों में कृत्रिमता और आत्मिक शांति का क्षय। समाज को यथार्थवादी, सादगीपूर्ण और प्राकृतिक जीवन अपनाने की आवश्यकता है।\n      </div>\n    </div>\n  </div>\n</section>","4":"<section class=\"chapter-section\" id=\"ch4\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">4</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (गद्य खंड) — पाठ 4</div>\n      <h2>एक कहानी यह भी</h2>\n      <p>मन्नू भंडारी | आत्मकथ्य — नारी चेतना, स्वतंत्रता आंदोलन, पितृसत्ता से संघर्ष और वैचारिक विकास | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch4-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">लेखिका के व्यक्तित्व पर किन-किन व्यक्तियों का किस रूप में प्रभाव पड़ा?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखिका मन्नू भंडारी के व्यक्तित्व के निर्माण में मुख्य रूप से दो व्यक्तियों का निर्णायक प्रभाव पड़ा:</p>\n          <ul>\n            <li><strong>पिता का प्रभाव:</strong> लेखिका के पिता ने उनके मन में हीनता की ग्रंथि (काले रंग और दुबलेपन के कारण) भी पैदा की, किंतु साथ ही उनमें देश-दुनिया के प्रति जागरूकता, राजनीतिक समझ और क्रांतिकारी विचार भरने का कार्य भी किया। पिता के शक्की स्वभाव और दंभ ने लेखिका के स्वाभिमान को धार दी।</li>\n            <li><strong>हिंदी प्राध्यापिका शीला अग्रवाल का प्रभाव:</strong> कॉलेज में शीला अग्रवाल ने लेखिका को केवल साहित्य पढ़ना ही नहीं सिखाया, बल्कि श्रेष्ठ साहित्य को परखने की दृष्टि दी। उन्होंने लेखिका के रगों में बहते खून को लावे में बदल दिया और उन्हें स्वाधीनता संग्राम की सक्रिय भागीदारी के लिए प्रेरित किया।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पिता के वैचारिक प्रभाव व अंतर्विरोधों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शीला अग्रवाल द्वारा साहित्य रुचि व चेतना जगाने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch4-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">मन्नू भंडारी के पिता के स्वभाव की क्या विशेषताएँ थीं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मन्नू भंडारी के पिता का व्यक्तित्व अंतर्विरोधों और जटिलताओं से भरा था:</p>\n          <ul>\n            <li><strong>विद्वान एवं संवेदनशील:</strong> वे अत्यंत कोमल हृदय, दरियादिल, सुशिक्षित और प्रतिष्ठित व्यक्ति थे। उन्होंने अंग्रेजी-हिंदी शब्दकोश का निर्माण किया था।</li>\n            <li><strong>क्रोधी और शक्की:</strong> आर्थिक झटकों और अपनों द्वारा दिए गए धोखों के कारण वे अत्यधिक क्रोधी, अहंवादी और संशयवादी बन गए थे।</li>\n            <li><strong>विरोधाभासी मानसिकता:</strong> वे एक ओर आधुनिक सोच रखते हुए बेटी को राजनीति व बहसों में शामिल करना चाहते थे, लेकिन दूसरी ओर परंपरावादी होकर उसे चारदीवारी के दायरे में ही रखना चाहते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विद्वत्ता व प्रतिष्ठा के साथ शक्की स्वभाव का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रूढ़िवादी व प्रगतिशील विचारों के द्वंद्व का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch4-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लेखिका के पिता ने रसोई को 'भटियारखाना' कहकर क्यों संबोधित किया?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखिका के पिता रसोई को 'भटियारखाना' इसलिए कहते थे क्योंकि उनका मानना था कि रसोई में लगातार काम करने से व्यक्ति की बौद्धिक क्षमता, प्रतिभा और रचनात्मक ऊर्जा नष्ट हो जाती है। वे अपनी बेटियों को केवल चूल्हे-चौके तक सीमित नहीं देखना चाहते थे, बल्कि देश और समाज की बौद्धिक बहसों में सक्रिय भागीदार बनाना चाहते थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रतिभा व क्षमता नष्ट होने के तर्क का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बौद्धिक विकास को प्राथमिकता देने का भाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch4-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">वह कौन-सी घटना थी जिसके बाद लेखिका को न अपनी आँखों पर विश्वास हो पाया और न अपने कानों पर?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>जब कॉलेज की प्रिंसिपल ने पत्र भेजकर लेखिका के पिता को कॉलेज बुलाया और शिकायत की कि मन्नू के एक इशारे पर लड़कियाँ क्लास छोड़ हड़ताल कर देती हैं, तो पिता क्रोधित होकर घर से निकले थे। लेखिका डरकर पड़ोस में बैठ गई कि घर लौटते ही पिता उसे पीटेंगे।</p>\n          <p>किंतु जब पिता कॉलेज से लौटे, तो वे बेहद खुश और गर्व से भरे हुए थे। उन्होंने कहा—\"पूरे कॉलेज पर मेरी बेटी का दबदबा है! यह तो स्वाधीनता आंदोलन की पुकार है, इसे कोई कैसे रोक सकता है!\" पिता का यह बदला हुआ रूप देखकर लेखिका को न अपनी आँखों पर विश्वास हुआ और न अपने कानों पर।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रिंसिपल की शिकायत और पिता के प्रारंभिक क्रोध का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पिता के गर्व और प्रशंसा भरे व्यवहार पर लेखिका का आश्चर्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch4-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">लेखिका की अपने पिता से वैचारिक टकराहट को अपने शब्दों में लिखिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखिका और उनके पिता में गहरी वैचारिक टकराहट थी, जो दोनों के विचारों के अंतर्विरोध से उपजी थी:</p>\n          <ul>\n            <li><strong>घर की सीमा बनाम खुले मैदान की स्वतंत्रता:</strong> पिता चाहते थे कि लेखिका घर में बैठकर राजनीतिक चर्चाएँ सुने और चिंतन करे, किंतु लेखिका नारों, जुलूसों और हड़तालों में सड़कों पर उतरकर सक्रिय क्रांति करना चाहती थी।</li>\n            <li><strong>समाज की प्रतिष्ठा की चिंता:</strong> पिता दकियानूसी समाज और पड़ोसियों की टीका-टिप्पणियों से भयभीत हो जाते थे, जबकि लेखिका सामाजिक बंधनों की परवाह किए बिना अपनी राह स्वयं चुनना चाहती थी।</li>\n            <li><strong>अहं का टकराव:</strong> पिता का अत्यधिक अहंवादी होना और लेखिका का विद्रोही स्वाभिमान दोनों में निरंतर द्वंद्व उत्पन्न करता था।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घर की चारदीवारी बनाम सक्रिय भागीदारी का द्वंद्व</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामाजिक भय बनाम विद्रोही स्वाभिमान का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> मन्नू भंडारी के पिता आधुनिक विचारों के समर्थक होते हुए भी पूरी तरह परंपरावादी थे।<br>\n        <strong>कारण (R):</strong> वे चाहते थे कि मन्नू देश-दुनिया की राजनीतिक बहसें सुने, परंतु सड़कों पर लड़कों के साथ हड़ताल व नारेबाज़ी न करे।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> पिता के व्यक्तित्व में विरोधाभास था—वे नारी प्रगति तो चाहते थे, लेकिन सामाजिक मर्यादा व प्रतिष्ठा की रूढ़िवादी बेड़ियों से मुक्त नहीं हो सके थे। अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 2: मूल्य-आधारित चिंतन प्रश्न (Value-Based Question)</div>\n      <div class=\"cbq-question\">\n        'एक कहानी यह भी' पाठ के आधार पर स्पष्ट कीजिए कि एक शिक्षक (जैसे शीला अग्रवाल) किसी विद्यार्थी की दिशा और सोच को किस प्रकार रूपांतरित कर सकता है?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        एक आदर्श शिक्षक केवल पाठ्यपुस्तकें नहीं पढ़ाता, बल्कि विद्यार्थी में छिपी हुई असीम संभावनाओं को जाग्रत करता है। शीला अग्रवाल ने मन्नू भंडारी को मात्र कक्षा का ज्ञान नहीं दिया, बल्कि श्रेष्ठ साहित्य का मर्म समझाया, उनमें स्वतंत्र चिंतन की ज्वाला जलाई और उन्हें स्वाधीनता संघर्ष में सक्रिय भूमिका निभाने का नैतिक साहस प्रदान किया। शिक्षक एक प्रकाश स्तंभ की तरह छात्र की सुप्त चेतना को सामाजिक उत्तरदायित्व में बदल देता है।\n      </div>\n    </div>\n  </div>\n</section>","5":"<section class=\"chapter-section\" id=\"ch5\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">5</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (गद्य खंड) — पाठ 5</div>\n      <h2>नौबतखाने में इबादत</h2>\n      <p>यतींद्र मिश्र | व्यक्तिचित्र — उस्ताद बिस्मिल्ला खाँ, शहनाई वादन, काशी की गंगा-जमुनी संस्कृति और साधना | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch5-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">शहनाई की दुनिया में डुमराँव को क्यों याद किया जाता है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>शहनाई की दुनिया में डुमराँव को दो प्रमुख कारणों से याद किया जाता है:</p>\n          <ol>\n            <li><strong>बिस्मिल्ला खाँ का जन्मस्थान:</strong> भारत रत्न से सम्मानित शहनाई के अद्वितीय वादक उस्ताद बिस्मिल्ला खाँ का जन्म डुमराँव (बिहार) में हुआ था।</li>\n            <li><strong>नरकट घास की उपलब्धता:</strong> शहनाई बजाने के लिए जिस 'रीड' की आवश्यकता होती है, वह अंदर से पोली घास 'नरकट' डुमराँव में सोन नदी के किनारों पर ही प्रचुर मात्रा में पाई जाती है। इसके बिना शहनाई का वादन संभव नहीं है।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बिस्मिल्ला खाँ के जन्मस्थल का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सोन नदी किनारे नरकट घास की रीड का महत्व</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch5-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">बिस्मिल्ला खाँ को शहनाई की 'मंगलध्वनि का नायक' क्यों कहा गया है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>भारतीय परंपरा में शहनाई विवाह, धार्मिक अनुष्ठान और मांगलिक अवसरों पर बजाई जाने वाली अत्यंत पावन ध्वनि है। बिस्मिल्ला खाँ को इसका नायक इसलिए कहा गया है क्योंकि:</p>\n          <ul>\n            <li>उन्होंने शहनाई को लोक-वाद्यों के सीमित घेरे से निकालकर शास्त्रीय संगीत के सर्वोच्च मंचों पर प्रतिष्ठित किया।</li>\n            <li>वे लगभग अस्सी वर्षों तक अखंड साधना के साथ शहनाई के माध्यम से सुरीली व मंगलकारी सुर-सृष्टि करते रहे।</li>\n            <li>उनकी शहनाई के सुरों में ईश्वर की इबादत, विनम्रता और शांति का वास था, जो हर श्रोता को पवित्र आनंद से भर देता था।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शहनाई को शास्त्रीय मंच पर प्रतिष्ठित करने का योगदान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अखंड साधना व सुरों की आध्यात्मिक पवित्रता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch5-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">सुषिर-वाद्यों से क्या अभिप्राय है? शहनाई को 'सुषिर वाद्यों में शाह' की उपाधि क्यों दी गई होगी?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>सुषिर-वाद्य:</strong> वे वाद्य यंत्र जो फूँक मारकर बजाए जाते हैं और जिनमें छिद्रों (नाड़ियों) के माध्यम से सुर निकाले जाते हैं, उन्हें 'सुषिर-वाद्य' कहा जाता है; जैसे—बाँसुरी, शहनाई, शंख आदि।</p>\n          <p><strong>'शाह-ने' (शाह) की उपाधि:</strong> अरब देश में फूँककर बजाए जाने वाले वाद्यों को 'नय' कहते हैं। शहनाई की बनावट अत्यंत सुरीली, मधुर और कर्णप्रिय होती है। सभी सुषिर वाद्यों में इसकी ध्वनि सर्वाधिक मनमोहक और राग-रागिनियों को प्रकट करने में सबसे समर्थ है, इसलिए इसे वाद्यों का राजा यानी 'शाह-ने' या 'शहनाई' कहा गया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सुषिर-वाद्य की सटीक परिभाषा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'शाह-ने' शब्द की व्युत्पत्ति और मधुरता का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch5-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">आशय स्पष्ट कीजिए— \"फ़टा सुर न बख्शें। लुंगिया का क्या है, आज फटी है, तो कल सिल जाएगी...\"</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>आशय:</strong> जब बिस्मिल्ला खाँ की शिष्या ने उन्हें फटी हुई तहमत (लुंगी) पहनने पर टोका और कहा कि अब आपको भारत रत्न मिल चुका है, तो खाँ साहब ने यह मार्मिक उत्तर दिया।</p>\n          <p>इस कथन का गहरा भाव यह है कि खाँ साहब के लिए बाह्य भौतिक चमक-दमक, कपड़े और मान-सम्मान का कोई मूल्य नहीं था। उनके लिए कला (सुर) की साधना सर्वोपरि थी। वे ईश्वर से केवल यही प्रार्थना करते थे कि उनकी कला में कभी कोई खोट (फटा सुर) न आए, क्योंकि वस्त्र तो साधारण वस्तु है जो फटने पर सिली जा सकती है, किंतु यदि साधना और सुर में दरार आ गई तो उसे कभी सुधारा नहीं जा सकता।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भौतिक ऐश्वर्य की तुलना में कला साधना की प्राथमिकता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">खाँ साहब की निरहंकारिता व सुर-समर्पण का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch5-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">बिस्मिल्ला खाँ के व्यक्तित्व की कौन-कौन सी विशेषताओं ने आपको सर्वाधिक प्रभावित किया?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>उस्ताद बिस्मिल्ला खाँ के व्यक्तित्व की निम्नलिखित विशेषताओं ने हमें गहराई से प्रभावित किया:</p>\n          <ul>\n            <li><strong>सादा जीवन और उच्च विचार:</strong> भारत रत्न प्राप्त करने के बाद भी वे फटी लुंगी पहनने में संकोच नहीं करते थे; उनमें तनिक भी अहंकार नहीं था।</li>\n            <li><strong>सांप्रदायिक सौहार्द के प्रतीक:</strong> वे सच्चे मुस्लिम होकर नमाज़ अदा करते थे, तो साथ ही काशी विश्वनाथ और बालाजी मंदिर के प्रति उनकी अटूट श्रद्धा थी। वे भारत की साझी गंगा-जमुनी संस्कृति के जीवंत प्रतीक थे।</li>\n            <li><strong>अविराम रियाज़ व समर्पण:</strong> अस्सी वर्ष की आयु में भी वे स्वयं को एक नौसिखिया मानकर ईश्वर से सच्चे सुर की नेमत माँगते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सादगी और विनम्रता का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धार्मिक सहिष्णुता व गंगा-जमुनी समन्वय</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निरंतर सीखने की लगन व रियाज़</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: केस-आधारित विश्लेषण (Case-Based Competency)</div>\n      <div class=\"cbq-question\">\n        \"काशी संस्कृति की पाठशाला है। शास्त्रों में आनंदकानन के नाम से पूजित। काशी में कलाधर हनुमान व नृत्य विश्वनाथ हैं। काशी में बिस्मिल्ला खाँ हैं।\" प्रस्तुत कथन के आलोक में स्पष्ट कीजिए कि बिस्मिल्ला खाँ काशी के सांस्कृतिक समन्वय के प्रतीक कैसे बने?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        बिस्मिल्ला खाँ भारत की साझी संस्कृति के साकार रूप थे। वे पाँचों वक्त नमाज़ पढ़ते थे, मुहर्रम में नौबत बजाकर रोते थे, और वहीं दूसरी ओर काशी विश्वनाथ और संकटमोचन मंदिर की ड्योढ़ी पर बैठकर शहनाई बजाते थे। जब भी काशी से बाहर जाते, तो सबसे पहले विश्वनाथ जी की दिशा में मुँह करके शहनाई का पहला सुर अर्पित करते थे। उनका यह आचरण सिद्ध करता है कि संगीत और संस्कृति किसी मजहब की सीमाओं में नहीं बँधती।\n      </div>\n    </div>\n  </div>\n</section>","6":"<section class=\"chapter-section\" id=\"ch6\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">6</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (गद्य खंड) — पाठ 6</div>\n      <h2>संस्कृति</h2>\n      <p>भदंत आनंद कौसल्यायन | विचारात्मक निबंध — सभ्यता और संस्कृति में अंतर, मानव कल्याण, त्याग और वैज्ञानिक दृष्टि | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch6-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">लेखक की दृष्टि में 'सभ्यता' और 'संस्कृति' की सही समझ अब तक क्यों नहीं बन पाई है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के अनुसार 'सभ्यता' और 'संस्कृति' ऐसे शब्द हैं जिनका उपयोग सबसे अधिक होता है, किंतु इन्हें सबसे कम समझा गया है। लोग इन दोनों शब्दों को प्रायः एक ही अर्थ में मिला देते हैं और इनके साथ 'भौतिक' या 'आध्यात्मिक' जैसे विशेषण जोड़कर इनके मूल अर्थ को और अधिक भ्रामक व उलझावपूर्ण बना देते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दोनों शब्दों के घालमेल और विशेषणों द्वारा उत्पन्न भ्रम का उल्लेख</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch6-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">आग की खोज एक बहुत बड़ी खोज क्यों मानी जाती है? इस खोज के पीछे रही प्रेरणा के मुख्य स्रोत क्या रहे होंगे?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>बड़ी खोज का कारण:</strong> आग की खोज ने मानव सभ्यता को अंधकार और कच्चे भोजन के आदिम युग से निकालकर प्रकाश, सुरक्षा और पके हुए भोजन के युग में पहुँचाया। इसने मनुष्य को अन्य प्राणियों से श्रेष्ठ बनाया।</p>\n          <p><strong>प्रेरणा के मुख्य स्रोत:</strong></p>\n          <ul>\n            <li>पेट की ज्वाला (भूख) शांत करने और भोजन को सुपाच्य बनाने की आवश्यकता।</li>\n            <li>अंधेरे और जंगली हिंसक पशुओं के भय से आत्मरक्षा की इच्छा।</li>\n            <li>शीत व ठंड से बचाव के लिए ऊष्मा (गर्मी) प्राप्त करने की चाहत।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मानव जीवन में आग के क्रांतिकारी प्रभाव का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भूख, भय व ठंड से बचाव की प्रेरणा का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch6-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">वास्तविक अर्थों में 'संस्कृत व्यक्ति' किसे कहा जा सकता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के अनुसार वास्तविक अर्थों में 'संस्कृत व्यक्ति' वह है जो अपनी मूल प्रज्ञा, बुद्धि और योग्यता के बल पर किसी सर्वथा नए तथ्य या वस्तु का पहली बार आविष्कार करता है। जैसे—जिसने पहली बार आग की खोज की या जिसने गुरुत्वाकर्षण का सिद्धांत खोजा (न्यूटन), वे संस्कृत व्यक्ति थे। केवल पूर्वजों की खोजों का उपभोग करने वाला व्यक्ति संस्कृत नहीं, बल्कि केवल 'सभ्य' होता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अपनी प्रज्ञा से नई वस्तु का आविष्कार करने का लक्षण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संस्कृत और सभ्य के बीच मौलिक अंतर</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch6-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">न्यूटन को 'संस्कृत मानव' कहा गया, लेकिन उनके बाद के वैज्ञानिकों को 'सभ्य' कहा गया, 'संस्कृत' नहीं—क्यों?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>न्यूटन ने अपनी मौलिक प्रतिभा और जिज्ञासा से गुरुत्वाकर्षण के सिद्धांत का सबसे पहले आविष्कार किया था, इसलिए वे 'संस्कृत मानव' थे। आज का भौतिक विज्ञान का विद्यार्थी न्यूटन से कहीं अधिक नियमों और गूढ़ रहस्यों को जानता है, परंतु वह ज्ञान उसने स्वयं अपनी मौलिक प्रज्ञा से नहीं खोजा, बल्कि न्यूटन और अन्य पूर्वजों से विरासत में पाया है। अतः आज का विद्यार्थी या वैज्ञानिक न्यूटन से अधिक 'सभ्य' तो हो सकता है, परंतु 'संस्कृत' नहीं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">न्यूटन द्वारा मौलिक खोज का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परवर्ती वैज्ञानिकों द्वारा विरासत में ज्ञान पाने का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch6-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">'मानव संस्कृति एक अविभाज्य वस्तु है'—स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मानव संस्कृति का मूल तत्व है—कल्याण की भावना, परोपकार, त्याग और सत्य की खोज। इसमें ऐसा कोई भी अंश नहीं है जो मनुष्य को मनुष्य से अलग करे। जब तक मनुष्य का चिंतन और कर्म समस्त मानव जाति के कल्याण से जुड़ा है, तब तक वह संस्कृति है। जब संस्कृति को संकीर्ण मजहब, जाति या राष्ट्र की सीमाओं में बाँटकर दूसरों के विनाश के लिए इस्तेमाल किया जाता है, तो वह संस्कृति नहीं बल्कि 'असंस्कृति' बन जाती है। अतः सच्ची संस्कृति अखंड और अविभाज्य है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कल्याण भावना और सार्वभौमिकता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संस्कृति और असंस्कृति का भेद व अखंडता का निष्कर्ष</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> जो आविष्कार मानव कल्याण की भावना से जुड़े नहीं होते, वे संस्कृति का परिणाम नहीं बल्कि असंस्कृति हैं।<br>\n        <strong>कारण (R):</strong> परमाणु बम और संहारक अस्त्रों का निर्माण आत्म-विनाश का साधन होने के कारण अप-संस्कृति को जन्म देता है।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> लेखक के अनुसार संस्कृति का मूल तत्व 'कल्याण' है। जब बुद्धि और विज्ञान का प्रयोग मानव जाति के विनाश के लिए होता है, तो वह असंस्कृति कहलाता है, अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n  </div>\n</section>","7":"<section class=\"chapter-section\" id=\"ch7\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">7</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (काव्य खंड) — पाठ 7</div>\n      <h2>पद</h2>\n      <p>सूरदास (सूरसागर के भ्रमरगीत से) | ब्रजभाषा — गोपियों का वाक्चातुर्य, अनन्य कृष्ण प्रेम और निर्गुण योग पर सगुण भक्ति की विजय | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch7-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">गोपियों द्वारा उद्धव को भाग्यवान कहने में क्या व्यंग्य निहित है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियाँ उद्धव को 'बड़भागी' (भाग्यवान) कहकर वास्तव में उन पर तीखा वक्रोक्तिपूर्ण व्यंग्य करती हैं। उनके कहने का वास्तविक भाव यह है कि उद्धव अत्यंत अभागे हैं:</p>\n          <ul>\n            <li>वे प्रेम के साक्षात् अवतार भगवान श्रीकृष्ण के इतने निकट रहते हैं, फिर भी उनके हृदय में प्रेम और अनुराग की एक बूँद भी उत्पन्न नहीं हो सकी।</li>\n            <li>वे प्रेम के अलौकिक आनंद और विरह-मिलन के दिव्य सुख से सर्वथा वंचित हैं। इसलिए गोपियों की दृष्टि में उनका यह अनासक्त जीवन निरर्थक और दुर्भाग्यपूर्ण है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वक्रोक्ति/व्यंग्य के स्वरूप का स्पष्टीकरण (भाग्यवान कहकर अभागा बताना)</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कृष्ण के सान्निध्य में रहकर भी प्रेमरहित रहने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">उद्धव के व्यवहार की तुलना किस-किस से की गई है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियों ने उद्धव के प्रेमहीन और अनासक्त व्यवहार की तुलना निम्नलिखित दो प्राकृतिक उदाहरणों से की है:</p>\n          <ol>\n            <li><strong>कमल के पत्ते (पुरइनि पात) से:</strong> जिस प्रकार कमल का पत्ता जल के भीतर रहते हुए भी जल से गीला नहीं होता और उस पर पानी की एक बूँद भी नहीं टिकती, उसी प्रकार उद्धव कृष्ण के समीप रहते हुए भी उनके प्रेम से अछूते हैं।</li>\n            <li><strong>तेल लगी गागर (गागरी) से:</strong> जिस प्रकार तेल से चुपड़े हुए मटके को जल में डुबोने पर उस पर पानी की एक बूँद भी नहीं ठहरती, उसी प्रकार ज्ञानमार्गी उद्धव पर कृष्ण के अगाध प्रेम-सागर का कोई असर नहीं होता।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कमल के पत्ते (पुरइनि पात) के उदाहरण का सटीक विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तेल लगी मटकी के उदाहरण का सटीक विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">उद्धव द्वारा दिए गए योग के संदेश ने गोपियों की विरहाग्नि में घी का काम कैसे किया?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियाँ मथुरा से श्रीकृष्ण के लौटने की प्रतीक्षा में तन और मन की विरह-वेदना को इस आशा के साथ सह रही थीं कि कृष्ण शीघ्र लौटेंगे और उनका प्रेम साकार होगा। किंतु जब उद्धव ने आकर उन्हें कृष्ण के प्रेम को भूलने और निर्गुण ब्रह्म की कठोर योग-साधना अपनाने का संदेश दिया, तो उनकी सारी आशाएँ टूट गईं।</p>\n          <p>जिस संदेश से उन्हें सांत्वना मिलने की उम्मीद थी, उसी ने उनकी विरह-व्यथा और पीड़ा को अत्यधिक भड़का दिया। इस प्रकार योग के संदेश ने जलती हुई विरहाग्नि में आहुति (घी) डालने का कार्य किया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मिलन की आशा के टूटने और निराशा का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">योग संदेश द्वारा विरह-वेदना भड़कने का रूपक</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">गोपियों ने उद्धव से योग की शिक्षा कैसे लोगों को देने की बात कही है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियों ने उद्धव से कहा—<em>\"यह तौ सूर तिनहिं लै सौंपौ, जिनके मन चक्री।\"</em></p>\n          <p>अर्थात यह निर्गुण योग का संदेश उन लोगों को जाकर सौंपिए जिनका मन चंचल, अस्थिर और चक्री (भौंरे या चक्र) के समान भटकता रहता है। गोपियों का मन तो एकमात्र श्रीकृष्ण के अनन्य प्रेम में दृढ़ और स्थिर है, इसलिए उन्हें किसी अन्य योग-साधना की लेशमात्र भी आवश्यकता नहीं है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अस्थिर व भटके हुए मन वाले लोगों को देने का सुझाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गोपियों के स्थिर व एकाग्र प्रेम का विपरीत भाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch7-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">प्रस्तुत पदों के आधार पर गोपियों का योग-साधना के प्रति दृष्टिकोण स्पष्ट करें।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गोपियों के लिए निर्गुण योग-साधना पूर्णतया निरर्थक, अरुचिकर और कष्टप्रद है:</p>\n          <ul>\n            <li><strong>कड़वी ककड़ी के समान:</strong> गोपियाँ कहती हैं कि योग का नाम सुनते ही मुँह का स्वाद कड़वी ककड़ी जैसा अरुचिकर हो जाता है (<em>'ज्यों करुई ककरी'</em>)।</li>\n            <li><strong>एक असाध्य बीमारी:</strong> वे योग को ऐसी भयानक व्याधि मानती हैं जिसे न कभी उन्होंने पहले देखा, न सुना और न ही कभी भोगा।</li>\n            <li>वे सगुण साकार प्रेम को ही मुक्ति और आनंद का सच्चा मार्ग मानती हैं तथा ज्ञानमार्ग पर प्रेममार्ग की श्रेष्ठता स्थापित करती हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कड़वी ककड़ी और बीमारी (व्याधि) के उपमानों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ज्ञान पर सगुण प्रेम की प्रतिष्ठा का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: काव्यांश-आधारित विश्लेषण (Extract-Based Competency)</div>\n      <div class=\"cbq-question\">\n        \"हमारे हरि हारिल की लकरी। मन क्रम बचन नंद-नंदन उर, यह दृढ़ करि पकरी॥\"<br>\n        प्रस्तुत पंक्तियों में हारिल पक्षी की लकड़ी का रूपक गोपियों की किस मानसिक अवस्था और भक्ति-भावना को दर्शाता है?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        हारिल पक्षी अपने पंजों में लकड़ी के तिनके को सदा पकड़े रहता है और उसे अपना एकमात्र जीवन-आधार मानता है। ठीक उसी प्रकार गोपियों ने मन, कर्म और वाणी से श्रीकृष्ण को अपने हृदय में दृढ़तापूर्वक धारण कर रखा है। यह रूपक उनके <strong>एकनिष्ठ, अनन्य और अडिग समर्पण</strong> को दर्शाता है, जहाँ कृष्ण के अतिरिक्त उनके जीवन का कोई अन्य अवलंबन नहीं है।\n      </div>\n    </div>\n  </div>\n</section>","8":"<section class=\"chapter-section\" id=\"ch8\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">8</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (काव्य खंड) — पाठ 8</div>\n      <h2>राम-लक्ष्मण-परशुराम संवाद</h2>\n      <p>गोस्वामी तुलसीदास (रामचरितमानस के बालकांड से) | अवधी भाषा, दोहा-चौपाई छंद — वीर रस, रौद्र रस, हास्य-व्यंग्य और मर्यादा | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch8-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">परशुराम के क्रोध करने पर लक्ष्मण ने धनुष के टूट जाने के लिए कौन-कौन से तर्क दिए?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लक्ष्मण ने हँसते हुए परशुराम के समक्ष निम्नलिखित तर्क प्रस्तुत किए:</p>\n          <ul>\n            <li><strong>बचपन के धनुषों की समानता:</strong> हमने बचपन में खेल-खेल में न जाने कितनी धनुहियाँ तोड़ डालीं, तब तो मुनिवर ने कभी ऐसा क्रोध नहीं किया। इस धनुष पर इतनी विशेष ममता क्यों?</li>\n            <li><strong>जीर्ण-शीर्ण पुराना धनुष:</strong> यह धनुष अत्यंत पुराना और जर्जर था। ऐसे सड़े-गले धनुष के टूटने से किसी को क्या लाभ या क्या हानि हो सकती है?</li>\n            <li><strong>राम का दोष नहीं:</strong> श्री राम ने तो इसे नए के भ्रम में केवल छुआ मात्र था, छूते ही यह अपने-आप टूट गया। इसमें रघुपति का कोई दोष नहीं है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बचपन की धनुहियों का तर्क</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धनुष के पुराने व जर्जर होने का तर्क</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">राम द्वारा केवल छूते ही टूटने का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch8-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">परशुराम के क्रोध करने पर राम और लक्ष्मण की जो प्रतिक्रियाएँ हुईं, उनके आधार पर दोनों के स्वभाव की विशेषताएँ अपने शब्दों में लिखिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>श्री राम का स्वभाव:</strong></p>\n          <ul>\n            <li><strong>धैर्य और विनम्रता:</strong> राम अत्यंत शांत, सौम्य और मर्यादा पुरुषोत्तम हैं। वे परशुराम के भीषण क्रोध के सामने हाथ जोड़कर स्वयं को उनका 'एक दास' कहते हैं।</li>\n            <li><strong>शीतलता:</strong> उनके वचन जल के समान शीतल और क्रोध को शांत करने वाले हैं। वे बड़ों का आदर करना भली-भाँति जानते हैं।</li>\n          </ul>\n          <p><strong>लक्ष्मण का स्वभाव:</strong></p>\n          <ul>\n            <li><strong>उग्रता और वाक्पटुता:</strong> लक्ष्मण स्वभाव से अत्यंत उग्र, तेजस्वी और निर्भीक हैं। वे अन्याय या अनुचित अहंकार को बिल्कुल सहन नहीं करते।</li>\n            <li><strong>व्यंग्यबाण:</strong> वे परशुराम के फरसे और डींगों से तनिक भी नहीं डरते, बल्कि तीखे व्यंग्य बाणों से उनके क्रोध को और भड़का देते हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">श्री राम के शील, विनय व मर्यादा का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लक्ष्मण की निर्भीकता, उग्रता व व्यंग्य-क्षमता का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch8-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लक्ष्मण ने वीर योद्धा की क्या-क्या विशेषताएँ बताईं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लक्ष्मण ने परशुराम को लक्ष्य करते हुए एक सच्चे शूरवीर की निम्नलिखित विशेषताएँ बताईं:</p>\n          <ul>\n            <li><strong>कर्म में विश्वास:</strong> शूरवीर युद्धभूमि में अपनी वीरता का पराक्रम दिखाते हैं, मुँह से अपनी प्रशंसा के ढोल नहीं पीटते (<em>\"सूर समर करनी करहिं नहिं जनावहिं आपु\"</em>)।</li>\n            <li><strong>डींगें न हाँकना:</strong> युद्ध में शत्रु को सामने पाकर केवल कायर व्यक्ति ही अपने पराक्रम की डींगें हाँकते हैं।</li>\n            <li><strong>धैर्य और शील:</strong> सच्चे वीर धीर, क्षोभरहित और गंभीर होते हैं तथा गाली देने जैसी अशोभनीय हरकतें नहीं करते।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">युद्धभूमि में कर्म प्रदर्शन बनाम आत्मप्रशंसा का भेद</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धैर्य, गंभीरता व अमर्यादित आचरण न करने का गुण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch8-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">साहस और शक्ति के साथ विनम्रता हो तो बेहतर है—इस कथन पर अपने विचार लिखिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>यह कथन शत-प्रतिशत सत्य है। साहस और शक्ति जब बिना विवेक और विनम्रता के प्रकट होते हैं, तो वे विनाशकारी अहंकार और आतंक बन जाते हैं, जैसा कि परशुराम के क्रोधी व्यवहार में दिखाई देता है।</p>\n          <p>किंतु जब साहस और शक्ति के साथ 'विनम्रता' जुड़ जाती है, तो वह मनुष्य को सर्वप्रिय, सम्मानीय और महान बना देती है, जैसा कि भगवान श्री राम के आचरण में देखने को मिलता है। विनम्रता शक्ति को संयम प्रदान करती है और व्यक्ति समाज को जोड़ने का कार्य करता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विनम्रता विहीन शक्ति के दुष्परिणाम (अहंकार) का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विनम्रता युक्त शक्ति की दिव्यता व प्रभाव (श्री राम का उदाहरण)</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: शिल्प सौंदर्य और भाषा विश्लेषण (Stylistic Competency)</div>\n      <div class=\"cbq-question\">\n        \"इहाँ कुम्हड़बतिया कोउ नाहीं। जे तरजनी देखि मरि जाहीं॥\" पंक्ति में निहित लोकोक्ति और लक्ष्मण के साहस का आशय स्पष्ट कीजिए।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        'कुम्हड़बतिया' काशीफल (कद्दू) का वह छोटा-सा कोमल फल होता है जो उँगली की छुअन या तर्जनी दिखाने से मुरझा जाता है। लक्ष्मण इस लोक-विश्वास के माध्यम से निर्भीकतापूर्वक कहते हैं कि हम कोई कमजोर या भयभीत होने वाले व्यक्ति नहीं हैं जो आपकी तर्जनी उँगली या फरसा देखकर डर से मर जाएँगे। यहाँ लक्ष्मण का अदम्य क्षत्रिय तेज और व्यंग्य मुखरित हुआ है।\n      </div>\n    </div>\n  </div>\n</section>","9":"<section class=\"chapter-section\" id=\"ch9\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">9</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (काव्य खंड) — पाठ 9</div>\n      <h2>आत्मकथ्य</h2>\n      <p>जयशंकर प्रसाद | छायावादी कविता — वैयक्तिक पीड़ा, जीवन का यथार्थ, अंतर्मुखी दृष्टि और विनम्र अभिव्यक्ति | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch9-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कवि आत्मकथा लिखने से क्यों बचना चाहता है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>छायावादी कवि जयशंकर प्रसाद निम्नलिखित कारणों से अपनी आत्मकथा लिखने से बचना चाहते हैं:</p>\n          <ul>\n            <li><strong>साधारण व अभावग्रस्त जीवन:</strong> कवि का मानना है कि उनका जीवन अत्यंत सामान्य और खाली गगरी की तरह रिक्त रहा है; उसमें कोई ऐसी महान उपलब्धि नहीं जिसे सुनकर दुनिया वाह-वाह करे।</li>\n            <li><strong>व्यथाओं का पुनर्जागरण:</strong> आत्मकथा लिखने से जीवन के पुराने घाव और सोई हुई वेदना पुनः हरी हो जाएगी।</li>\n            <li><strong>उपहास का भय:</strong> वे अपनी कमजोरियों, भूलों और मित्रों द्वारा दिए गए छल-कपट को सार्वजनिक करके दुनिया में खुद को उपहास का पात्र नहीं बनाना चाहते।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उपलब्धिहीन सामान्य जीवन की अनुभूति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निजी वेदना के जागने व उपहास से बचने की भावना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch9-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">आत्मकथा सुनाने के संदर्भ में 'अभी समय भी नहीं' कवि ऐसा क्यों कहता है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि ऐसा इसलिए कहता है क्योंकि उसके अनुसार उसने अभी तक जीवन में कोई ऐसा महान कार्य या कीर्ति अर्जित नहीं की है जिसे समाज के सामने प्रस्तुत किया जाए। साथ ही, उसके हृदय की पीड़ा और दुखद स्मृतियाँ इस समय शांत होकर थकी-हारी सोई हुई हैं। कवि उन्हें जगाकर अपनी व्यथा को फिर से बढ़ाना नहीं चाहता।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">महान उपलब्धि के अभाव का तर्क</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सोई हुई व्यथा को न जगाने की इच्छा</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch9-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">स्मृति को 'पाथेय' बनाने से कवि का क्या आशय है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>'पाथेय' का अर्थ होता है—मार्ग का संबल या यात्रा में यात्री के काम आने वाला भोजन व सहारा।</p>\n          <p>कवि के जीवन में आज केवल सूनापन, दुख और निराशा है। अतीत में प्रियतमा के साथ बिताए गए सुखद क्षणों की मधुर स्मृतियाँ ही कवि के थके हुए जीवन रूपी यात्री का एकमात्र सहारा (पाथेय) हैं। उन्हीं स्मृतियों के सहारे वह अपने उदास जीवन की कठिन यात्रा तय कर रहा है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'पाथेय' शब्द का अर्थ (मार्ग का संबल)</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अतीत की सुखद स्मृतियों को जीने का सहारा मानने का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch9-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए— \"मिला कहाँ वह सुख जिसका मैं स्वप्न देखकर जाग गया। आलिंगन में आते-आते मुसक्या कर जो भाग गया।\"</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>भावार्थ:</strong> कवि यह कहना चाहता है कि जीवन में सुख उसके लिए एक स्वप्न मात्र बनकर रह गया। जिस सुख की उसने कल्पना की थी और जिसे वह अपनी बाहों में भरने ही वाला था, वह सुख उसे छूकर दूर छिटक गया।</p>\n          <p>अर्थात सांसारिक सुख क्षणभंगुर और छलावा सिद्ध हुए। कवि को वास्तविक जीवन में चिरस्थायी सुख की प्राप्ति कभी नहीं हुई, केवल विरह और निराशा ही उसकी नियति बनी।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सुख की क्षणभंगुरता व छलावे का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कवि के जीवन की निराशा व अतृप्ति का यथार्थ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: छायावादी शिल्प सौंदर्य (Poetic Aesthetic Competency)</div>\n      <div class=\"cbq-question\">\n        'आत्मकथ्य' कविता छायावादी काव्यधारा की प्रमुख विशेषताओं (मानवीकरण, प्रतीकात्मकता, तत्सम शब्दावली) को किस प्रकार प्रमाणित करती है?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        कविता में छायावाद की प्रमुख विशेषताएँ स्पष्ट परिलक्षित होती हैं:<br>\n        1. <strong>प्रतीकात्मकता:</strong> 'मधुप', 'रीति गागर', 'मुरझाकर गिरती पत्तियाँ' जीवन के अभावों के सशक्त प्रतीक हैं।<br>\n        2. <strong>मानवीकरण:</strong> <em>\"अरी सरलते तेरी हँसी उड़ाऊँ मैं\"</em> में सरलता का मानवीयकरण है।<br>\n        3. <strong>संस्कृतनिष्ठ तत्सम पदावली:</strong> 'अनंत नीलिमा', 'व्यंग्य-मलिन', 'अरुण-कपोलों' आदि शब्दों का सुंदर संयोजन कविता को विशिष्ट सौंदर्य प्रदान करता है।\n      </div>\n    </div>\n  </div>\n</section>","10":"<section class=\"chapter-section\" id=\"ch10\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">10</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (काव्य खंड) — पाठ 10</div>\n      <h2>उत्साह और अट नहीं रही है</h2>\n      <p>सूर्यकांत त्रिपाठी 'निराला' | आह्वान गीत व प्रकृति-गीत — क्रांति चेतना, सामाजिक परिवर्तन और फागुन मास का अनुपम सौंदर्य | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch10-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कवि बादल से फुहार, रिमझिम या बरसने के स्थान पर 'गरजो' क्यों कहता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि निराला एक क्रांतिकारी कवि हैं। वे बादल को केवल जल बरसाने वाले प्राकृतिक साधन के रूप में नहीं, बल्कि शोषित समाज में नई चेतना और क्रांति के प्रतीक के रूप में देखते हैं।</p>\n          <p>फुहार या रिमझिम कोमलता और शांति की सूचक है, जिससे समाज में बड़ा परिवर्तन नहीं आ सकता। कवि बादलों के भीषण 'गर्जन' के द्वारा समाज के सोए हुए लोगों में नवजीवन, पौरुष, उत्साह और विप्लव (क्रांति) का शंखनाद करना चाहता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बादल को क्रांति व पौरुष के प्रतीक के रूप में दर्शाना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">फुहार की कोमलता बनाम गर्जन के क्रांतिकारी प्रभाव का भेद</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch10-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">कविता का शीर्षक 'उत्साह' क्यों रखा गया है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कविता एक आह्वान गीत है जो मानव मन में उमंग, साहस और ऊर्जा भरने का संदेश देता है। जिस प्रकार बादलों का गर्जन और बरसना पीड़ित धरती और व्याकुल जन-मन में नई आशा और उत्साह का संचार करता है, उसी प्रकार क्रांति भी समाज में नवीन ऊर्जा भरती है। अतः 'उत्साह' शीर्षक सर्वथा सटीक और सार्थक है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आह्वान गीत के रूप में ऊर्जा व साहस जगाने का भाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शीर्षक की औचित्यपूर्ण सार्थकता</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch10-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">कविता में बादल किन-किन अर्थों की ओर संकेत करता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>'उत्साह' कविता में बादल निम्नलिखित बहुआयामी अर्थों की ओर संकेत करता है:</p>\n          <ol>\n            <li><strong>तप्त मानव की प्यास बुझाने वाले:</strong> गर्मी से पीड़ित और व्याकुल लोगों को शीतलता व जल प्रदान करने वाले कल्याणकारी रूप में।</li>\n            <li><strong>क्रांतिकारी चेतना के अग्रदूत:</strong> अपने वज्र-गर्जन से पुरानी रूढ़ियों को तोड़कर सामाजिक परिवर्तन लाने वाले विद्रोही रूप में।</li>\n            <li><strong>नवीन सृष्टि के रचयिता कवि:</strong> नए अंकुर को जीवन देने वाले और साहित्य में नवचेतना भरने वाले सृजक के रूप में।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तृष्णा निवारक व जलदाता रूप</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">क्रांति व परिवर्तन का प्रतीक</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सृजन व नई कविता का प्रतीक</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch10-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">'अट नहीं रही है' कविता के आधार पर फागुन के प्राकृतिक सौंदर्य का वर्णन कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>फागुन मास (वसंत ऋतु) में प्रकृति का सौंदर्य चरम सीमा पर होता है:</p>\n          <ul>\n            <li><strong>चारों ओर हरियाली और लालिमा:</strong> पेड़ों की डालियाँ कहीं हरी पत्तियों से तो कहीं लाल-लाल कोमल कोंपलों से लद गई हैं।</li>\n            <li><strong>सुगंधित समीर:</strong> फूलों से सुशोभित प्रकृति के गले में मानो मंद-मंद सुगंध की माला पड़ी हुई है, जिससे सारा वातावरण महक रहा है।</li>\n            <li><strong>असीमित शोभा:</strong> फागुन की प्राकृतिक आभा (शोभा) इतनी अधिक और व्यापक है कि वह प्रकृति और आँखों में समा नहीं पा रही है (अट नहीं रही है)।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पेड़ों पर नए पत्तों व फूलों का सुंदर चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मादक सुगंध व प्रकृति में समा न पाने वाले सौंदर्य का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> 'उत्साह' कविता में निराला जी बादलों को क्रांति का अग्रदूत मानते हैं।<br>\n        <strong>कारण (R):</strong> बादल अपने भीतर 'वज्र' छिपाए हुए हैं जो पुरानी सड़ी-गली व्यवस्था को नष्ट कर नवसृजन करने में सक्षम है।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> निराला जी के अनुसार बादलों के उर (हृदय) में छिपी बिजली और गर्जन विध्वंस के साथ-साथ नई कविता और नए जीवन का निर्माण करती है। अतः (R) बिल्कुल सही व्याख्या है।\n      </div>\n    </div>\n  </div>\n</section>","11":"<section class=\"chapter-section\" id=\"ch11\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">11</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (काव्य खंड) — पाठ 11</div>\n      <h2>यह दंतुरित मुस्कान और फसल</h2>\n      <p>नागार्जुन | जनवादी कविता — वात्सल्य रस, शिशु की मासूमियत, श्रम का गौरव और प्रकृति-मानव का सह-अस्तित्व | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch11-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">बच्चे की दंतुरित मुस्कान का कवि के मन पर क्या प्रभाव पड़ता है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>नन्हें बच्चे की नए-नए दाँत निकली (दंतुरित) मुस्कान देखकर कवि का मन अपार वात्सल्य और आनंद से भर उठता है:</p>\n          <ul>\n            <li><strong>मुरझाए मन में नवजीवन:</strong> कवि को लगता है कि बच्चे की यह मोहक मुस्कान मृतप्राय और निराश व्यक्ति में भी नए प्राण फूँक सकती है।</li>\n            <li><strong>कमल खिलने की अनुभूति:</strong> धूल-धूसरित बच्चे को देखकर लगता है मानो तालाब को छोड़कर कमल का फूल उसकी झोपड़ी में खिल उठा हो।</li>\n            <li><strong>कठोरता का पिघलना:</strong> कवि का मन जो लंबे प्रवास के कारण कठोर और शुष्क हो गया था, वह बच्चे के स्पर्श मात्र से पिघलकर शेफालिका के फूलों की तरह झड़ने लगता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निराशा में नवजीवन व वात्सल्य के संचार का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कमल व शेफालिका के फूलों जैसे बिंबों का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch11-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">बच्चे की मुसकान और एक बड़े व्यक्ति की मुस्कान में क्या अंतर होता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बच्चे और बड़े व्यक्ति की मुस्कान में मौलिक अंतर होता है:</p>\n          <ul>\n            <li><strong>बच्चे की मुस्कान:</strong> पूर्णतया निष्कपट, निश्छल, स्वाभाविक और स्वार्थहीन होती है। इसमें कोई बनावटीपन नहीं होता और यह हर देखने वाले को निर्मल आनंद देती है।</li>\n            <li><strong>बड़े व्यक्ति की मुस्कान:</strong> प्रायः औपचारिकता, स्वार्थ, कूटनीति या व्यंग्य से भरी होती है। बड़ों की मुस्कान में अवसरवादिता और संकोच छिपा रहता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बच्चे की निश्छलता व स्वाभाविकता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बड़ों की मुस्कान की कृत्रिमता व औपचारिकता का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch11-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">'फसल' कविता के आधार पर स्पष्ट कीजिए कि फसल क्या है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि नागार्जुन के अनुसार फसल किसी एक तत्व का परिणाम नहीं है, बल्कि प्रकृति और मानव-श्रम के अद्भुत समन्वय का फल है:</p>\n          <ol>\n            <li>हजार-हजार नदियों के अमृत-समान जल का जादुई प्रभाव।</li>\n            <li>करोड़ों कर्मठ किसानों और मजदूरों के हाथों के कठोर परिश्रम व स्पर्श की गरिमा।</li>\n            <li>विभिन्न प्रकार की उपजाऊ मिट्टियों (काली, दोमट, संदली) के पोषक तत्वों का सम्मिश्रण।</li>\n            <li>सूरज की किरणों की ऊर्जा और वायु की मंद थिरकन का रूपांतरण।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रकृति के तत्वों (जल, मिट्टी, धूप, हवा) का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">करोड़ों किसानों के श्रम के योगदान की महत्ता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch11-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">'फसल को हाथों के स्पर्श की गरिमा और महिमा' कहकर कवि क्या व्यक्त करना चाहता है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि यह स्पष्ट करना चाहता है कि यद्यपि प्रकृति (मिट्टी, जल, धूप) फसल के विकास के लिए कच्चा माल देती है, किंतु जब तक किसान और मजदूर अपने पसीने और हाथों के स्पर्श से उसकी जुताई, बुवाई और सींचन नहीं करते, तब तक अन्न का दाना नहीं उग सकता। कवि यहाँ श्रमिक वर्ग के श्रम के प्रति गहरी कृतज्ञता और सम्मान व्यक्त कर रहा है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मानव श्रम के बिना प्राकृतिक तत्वों की निष्फलता</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">किसान के श्रम की गरिमा व प्रतिष्ठा</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: केस-आधारित पर्यावरण व श्रम चेतना (Competency Question)</div>\n      <div class=\"cbq-question\">\n        वर्तमान उपभोक्तावादी युग में कृषि और किसान की उपेक्षा बढ़ती जा रही है। नागार्जुन की कविता 'फसल' आज के संदर्भ में हमें पर्यावरण और कृषक समाज के प्रति क्या दृष्टिकोण अपनाने की प्रेरणा देती है?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        कविता यह सिद्ध करती है कि मानव जीवन की उत्तरजीविता प्रकृति (नदियों की शुचिता, मिट्टी की उर्वरता) और किसानों के पसीने पर टिकी है। यदि हम नदियों को प्रदूषित करेंगे, रासायनिक खादों से मिट्टी की शक्ति नष्ट करेंगे या अन्नदाता किसान के श्रम का यथोचित सम्मान नहीं करेंगे, तो हमारी खाद्य सुरक्षा और अस्तित्व संकट में पड़ जाएगा। अतः हमें प्रकृति का संरक्षण और कृषक वर्ग का सम्मान करना अनिवार्य है।\n      </div>\n    </div>\n  </div>\n</section>","12":"<section class=\"chapter-section\" id=\"ch12\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">12</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-2 (काव्य खंड) — पाठ 12</div>\n      <h2>संगतकार</h2>\n      <p>मंगलेश डबराल | समकालीन कविता — पृष्ठभूमि के सहायकों की भूमिका, निस्वार्थ योगदान और मानवीय संवेदना | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch12-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">संगतकार के माध्यम से कवि किस प्रकार के व्यक्तियों की ओर संकेत करना चाह रहा है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>संगतकार के माध्यम से कवि समाज के उन समस्त सहकर्मियों, सहायकों और पृष्ठभूमि में रहकर काम करने वाले व्यक्तियों की ओर संकेत कर रहा है, जो किसी भी मुख्य नायक, नेता, अभिनेता या संस्था की सफलता में रीढ़ की हड्डी की तरह कार्य करते हैं। वे स्वयं कभी प्रसिद्धि के केंद्र में नहीं आते, बल्कि पर्दे के पीछे रहकर मुख्य व्यक्ति को ऊँचाइयों पर पहुँचाने के लिए अपना सर्वस्व न्योछावर कर देते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पर्दे के पीछे कार्य करने वाले सहायकों का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मुख्य नायक की सफलता में निस्वार्थ योगदान का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch12-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">संगतकार जैसे व्यक्ति संगीत के अलावा और किन-किन क्षेत्रों में दिखाई देते हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>संगतकार जैसे समर्पित व्यक्ति जीवन के प्रत्येक क्षेत्र में मौजूद रहते हैं:</p>\n          <ul>\n            <li><strong>खेल के मैदान में:</strong> क्रिकेट या फुटबॉल में कप्तान के अलावा वे खिलाड़ी जो फील्डिंग, पासिंग या रणनीति में चुपचाप योगदान देते हैं; तथा कोच व सपोर्ट स्टाफ।</li>\n            <li><strong>सिनेमा और नाटक:</strong> मुख्य अभिनेता की सफलता के पीछे काम करने वाले निर्देशक, कैमरामैन, स्पॉटबॉय, मेकअप आर्टिस्ट और सह-कलाकार।</li>\n            <li><strong>राजनीति और समाज सेवा:</strong> बड़े नेता की रैलियों और चुनावी जीत की तैयारी करने वाले जमीनी कार्यकर्ता।</li>\n            <li><strong>चिकित्सा क्षेत्र:</strong> सफल शल्य-चिकित्सा (सर्जरी) में मुख्य सर्जन की सहायता करने वाले एनेस्थेटिस्ट और नर्सें।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">खेल व सिनेमा के उदाहरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">राजनीति व चिकित्सा/शल्य के उदाहरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch12-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">कवि ने संगतकार की आवाज में जो हिचक बताई है, उसे उसकी असफलता न मानकर 'मनुष्यता' क्यों कहा गया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>संगतकार में मुख्य गायक से भी ऊँचा और बेहतर गाने की योग्यता व प्रतिभा हो सकती है, किंतु वह कभी जानबूझकर अपनी आवाज़ को मुख्य गायक की आवाज़ से ऊपर नहीं उठने देता।</p>\n          <p>उसकी यह हिचक उसकी किसी कमजोरी या अक्षमता की परिचायक नहीं है, बल्कि यह उसके मन में मुख्य गायक के प्रति अपार आदर, गुरु-शिष्य की मर्यादा और निस्वार्थ त्याग की भावना है। वह अपने अहंकार को दबाकर मुख्य गायक की प्रतिष्ठा की रक्षा करता है, इसलिए कवि इसे उसकी कमजोरी न मानकर सर्वोच्च 'मनुष्यता' कहता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रतिभा होते हुए भी स्वयं को संयमित रखने का गुण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मुख्य गायक के सम्मान व त्याग को मनुष्यता मानने का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> संगतकार मुख्य गायक के बिखरते हुए आत्मविश्वास को पुनः संबल प्रदान करता है।<br>\n        <strong>कारण (R):</strong> जब तारसप्तक में मुख्य गायक का गला बैठने लगता है और उत्साह बुझने लगता है, तब संगतकार अपने ढाढ़स बँधाते स्वर से गीत की टेक को संभाल लेता है।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> संगतकार मुख्य गायक को कभी अकेला महसूस नहीं होने देता और तारसप्तक की जटिल तानों के समय स्थायी को पकड़कर उसकी गरिमा को गिरने से बचाता है, अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n  </div>\n</section>","13":"<section class=\"chapter-section\" id=\"ch13\" data-book=\"kritika\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">13</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">कृतिका भाग-2 — पाठ 1</div>\n      <h2>माता का आँचल</h2>\n      <p>शिवपूजन सहाय (उपन्यास 'देहाती दुनिया' से) | संस्मरण — ग्रामीण बाल्यकाल, वात्सल्य, पिता-पुत्र का स्नेह और संकट में मातृ-छाया | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch13-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">प्रस्तुत पाठ के आधार पर यह कहा जा सकता है कि बच्चे का अपने पिता से अधिक जुड़ाव था, फिर भी विपदा के समय वह पिता के पास न जाकर माँ की शरण लेता है। आपकी समझ से इसकी क्या वजह हो सकती है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>भोलानाथ का अधिकांश समय पिता के साथ ही बीतता था—पिता ही उसे नहलाते-धुलाते, पूजा में बिठाते, साथ खिलाते और घुमाने ले जाते थे। माँ से उसका संबंध केवल दूध पीने तक सीमित प्रतीत होता था।</p>\n          <p>किंतु जब बच्चे पर साँप का भीषण भय और विपदा आई, तो वह बाहर बैठे पिता के पास न जाकर सीधा अंदर माँ की गोद में जाकर छिप गया। इसके प्रमुख कारण निम्नलिखित हैं:</p>\n          <ul>\n            <li><strong>सुरक्षा और शांति की चरम अनुभूति:</strong> माँ का आँचल बच्चे के लिए प्रेम, ममता और सुरक्षा का सबसे अभेद्य किला होता है। संकट की घड़ी में माँ के हृदय की धड़कन बच्चे के भय को तुरंत शांत कर देती है।</li>\n            <li><strong>सहज वात्सल्य और ममता:</strong> माँ के आँचल में जो ममतामयी गर्माहट, कोमलता और अश्रुपूरित सहानुभूति मिलती है, वह पिता के संरक्षण में नहीं मिल पाती। माँ बच्चे के दर्द को देखकर स्वयं रो पड़ती है और अपनी छाती से चिपका लेती है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पिता के साथ दैनिक दिनचर्या व जुड़ाव का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">माँ के आँचल में सुरक्षा, ममता व शांति की मनोवैज्ञानिक व्याख्या</span><span class=\"marking-marks\">2.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch13-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">आपके विचार से भोलानाथ अपने साथियों को देखकर सिसकना क्यों भूल जाता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बाल-मन स्वभाव से अत्यंत चंचल, खेलप्रिय और साथी-उन्मुख होता है। जब भोलानाथ माँ द्वारा कड़वा तेल लगाने और चोटी गूँथने पर रोने-सिसकने लगता था, तब पिता उसे गोद में उठाकर बाहर लाते थे।</p>\n          <p>किंतु जैसे ही भोलानाथ बाहर अपनी हमउम्र बाल-मंडली को तरह-तरह के खेल खेलते और हुल्लड़ मचाते देखता, उसका ध्यान अपने दुख-दर्द से हटकर खेल के आकर्षण में खो जाता था। बाल-मनोविज्ञान के अनुसार साथियों का संग बच्चों के हर दुख को भुला देता है, इसलिए वह तुरंत सिसकना भूल जाता था।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाल-मन की खेलप्रियता व चंचलता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मित्र-मंडली के आकर्षण द्वारा दुख भूलने का मनोवैज्ञानिक विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch13-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">'माता का आँचल' शीर्षक की सार्थकता स्पष्ट कीजिए। क्या आप इसके लिए कोई अन्य शीर्षक सुझा सकते हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>शीर्षक की सार्थकता:</strong> यह शीर्षक अत्यंत उपयुक्त, मार्मिक और सार्थक है। पूरे पाठ में भले ही पिता के लाड़-प्यार और बाल-क्रीड़ाओं का विस्तार है, किंतु कहानी का चरम बिंदु (क्लाइमेक्स) वह क्षण है जब साँप से भयभीत होकर लहूलुहान बच्चा अंततः अपनी माँ के आँचल में आकर ही परम शांति और अभय प्राप्त करता है। माँ का आँचल ममता और संरक्षण की पराकाष्ठा है।</p>\n          <p><strong>वैकल्पिक शीर्षक:</strong> इसके अन्य उपयुक्त शीर्षक हो सकते हैं—<em>'भोलानाथ का बचपन'</em> अथवा <em>'मेरा बाल्यकाल'</em> अथवा <em>'माँ की ममता'</em>।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चरम बिंदु (क्लाइमेक्स) के आधार पर औचित्य सिद्ध करना</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सार्थक वैकल्पिक शीर्षक का सुझाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: केस-आधारित बाल-संस्कृति तुलना (Competency Question)</div>\n      <div class=\"cbq-question\">\n        'माता का आँचल' में वर्णित 1930 के दशक के बच्चों के खेल (धूल, मिट्टी, ठीकरे, पत्ते) और आज के बच्चों के डिजिटल खेलों (मोबाइल, वीडियो गेम्स) के बीच अंतर स्पष्ट करते हुए बताइए कि कौन-से खेल बच्चे के सर्वांगीण विकास के लिए अधिक हितकारी हैं?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        पाठ में वर्णित खेल प्रकृति के सान्निध्य में खेले जाते थे, जिनमें सामूहिक सहयोग, सामाजिक अंतःक्रिया, शारीरिक व्यायाम और असीम रचनात्मकता थी। बच्चे मिट्टी-पानी से जुड़कर जीवन की वास्तविकताओं को सीखते थे।<br>\n        इसके विपरीत आज के डिजिटल खेल बच्चों को चारदीवारी में एकाकी, आक्रामक और शारीरिक रूप से निष्क्रिय बना रहे हैं। अतः सर्वांगीण विकास (शारीरिक, मानसिक व सामाजिक) के लिए प्रकृति और साथियों के साथ खेले जाने वाले पारंपरिक खेल ही अधिक हितकारी हैं।\n      </div>\n    </div>\n  </div>\n</section>","14":"<section class=\"chapter-section\" id=\"ch14\" data-book=\"kritika\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">14</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">कृतिका भाग-2 — पाठ 2</div>\n      <h2>साना-साना हाथ जोड़ि...</h2>\n      <p>मधु कांकरिया | यात्रा-वृत्तांत — पूर्वोत्तर भारत (सिक्किम, हिमालय, गंतोक), प्राकृतिक भव्यता और श्रमसाध्य जीवन की त्रासदी | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch14-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">गंतोक को 'मेहनतकश बादशाहों का शहर' क्यों कहा गया है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>गंतोक (सिक्किम) एक ऐसा पर्वतीय शहर है जिसका सौंदर्य वहाँ के निवासियों के कठोर परिश्रम और पसीने से निर्मित हुआ है:</p>\n          <ul>\n            <li>वहाँ के स्त्री-पुरुष और बच्चे विषम भौगोलिक परिस्थितियों, बर्फीली ठंड और पथरीले रास्तों के बीच भी निरंतर कठिन श्रम करते हैं।</li>\n            <li>इतनी विपदाओं और परिश्रम के बावजूद वे कभी निराश नहीं होते, बल्कि राजाओं (बादशाहों) की तरह स्वाभिमान, मस्ती और संतोष के साथ जीवन जीते हैं। उनके अथक श्रम ने ही गंतोक को इतना सुरम्य बनाया है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कठिन भौगोलिक परिस्थितियों में कठोर परिश्रम का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वाभिमानी, संतुष्ट और बादशाही जीवन-शैली का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch14-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">कभी श्वेत तो कभी रंगीन पताकाओं का फहराना किन अलग-अलग अवसरों की ओर संकेत करता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>सिक्किम में बौद्ध धर्म की मान्यता के अनुसार पताकाएँ फहराई जाती हैं:</p>\n          <ul>\n            <li><strong>श्वेत पताकाएँ:</strong> जब किसी बौद्ध धर्मावलंबी की मृत्यु होती है, तो उसकी आत्मा की शांति के लिए शहर से दूर किसी पवित्र स्थान पर 108 श्वेत पताकाएँ फहराई जाती हैं। इन पर मंत्र लिखे होते हैं और इन्हें उतारा नहीं जाता, ये अपने-आप नष्ट होती हैं।</li>\n            <li><strong>रंगीन पताकाएँ:</strong> जब किसी नए कार्य का शुभ आरंभ किया जाता है, तब मांगलिक प्रतीक के रूप में रंग-बिरंगी पताकाएँ लगाई जाती हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">श्वेत पताकाओं का संदर्भ (शोक/शांति)</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रंगीन पताकाओं का संदर्भ (नए कार्य का शुभारंभ)</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch14-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">पत्थर तोड़ती पहाड़ियों के सौंदर्य और उनके कठिन जीवन के अंतर्विरोध को लेखिका ने किस प्रकार चित्रित किया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखिका ने प्राकृतिक सौंदर्य के बीच जीवन के कठोर यथार्थ का मार्मिक अंतर्विरोध प्रस्तुत किया है:</p>\n          <ul>\n            <li>एक ओर हिमालय का स्वर्गीय सौंदर्य, हरी-भरी वादियाँ और कलकल बहते झरने हैं जो मन को मुग्ध कर देते हैं।</li>\n            <li>वहीं दूसरी ओर, कोमल काया वाली पहाड़ी स्त्रियाँ पीठ पर बंधी डोको (बड़ी टोकरी) में अपने नन्हें बच्चों को बाँधकर हाथों में हथौड़े और कुदाल लिए कठोर पत्थर तोड़ रही हैं।</li>\n            <li>लेखिका को यह देखकर गहरा आघात लगता है कि इस अलौकिक सौंदर्य के बीच 'मातृत्व और श्रम-साधना' एक साथ जीवित है। स्वर्ग जैसी प्रकृति के आँचल में भूख और मौत से जूझता हुआ यह कठिन संघर्ष दिल को दहला देता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हिमालयी सौंदर्य बनाम पहाड़ी महिलाओं के श्रम का द्वंद्व</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मातृत्व और कठोर श्रम के संगम का मार्मिक चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: पर्यावरण संतुलन और जल संचय (Environmental Competency)</div>\n      <div class=\"cbq-question\">\n        \"प्रकृति ने जल संचय की कितनी अद्भुत व्यवस्था की है!\" लेखिका द्वारा किए गए इस कथन के आधार पर बताइए कि हिमालय किस प्रकार संपूर्ण एशिया के लिए जल-स्तंभ का कार्य करता है?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        सर्दियों में प्रकृति बर्फ के रूप में जल का विशाल संचय करती है। जब ग्रीष्म ऋतु में मैदानी भागों में पानी के लिए त्राहि-त्राहि मचती है, तब यही हिमशिखर धीरे-धीरे पिघलकर पावन नदियों के रूप में बह निकलते हैं और करोड़ों प्यासे कंठों को तृप्त करते हैं। प्रकृति का यह हिम-जल बैंक संपूर्ण एशिया की जीवनरेखा है।\n      </div>\n    </div>\n  </div>\n</section>","15":"<section class=\"chapter-section\" id=\"ch15\" data-book=\"kritika\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">15</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">कृतिका भाग-2 — पाठ 3</div>\n      <h2>मैं क्यों लिखता हूँ?</h2>\n      <p>सच्चिदानंद हीरानंद वात्स्यायन 'अज्ञेय' | निबंध — सर्जनात्मक प्रेरणा, आंतरिक विवशता, हिरोशिमा का आणविक संत्रास और अनुभूति | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch15-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">लेखक के अनुसार प्रत्यक्ष अनुभव की अपेक्षा 'अनुभूति' उनके लेखन में कहीं अधिक मदद करती है, क्यों?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के अनुसार 'प्रत्यक्ष अनुभव' और 'अनुभूति' में गहरा अंतर होता है:</p>\n          <ul>\n            <li><strong>प्रत्यक्ष अनुभव:</strong> वह बाह्य घटना है जो आँखों के सामने घटित होती है और हमारी इंद्रियों को छूकर निकल जाती है। यह केवल यथार्थ का साक्षात्कार कराता है।</li>\n            <li><strong>अनुभूति:</strong> जब वही अनुभव मन, आत्मा और संवेदना की गहराई में उतरकर लेखक की आंतरिक पीड़ा या भाव बन जाता है, तब वह 'अनुभूति' बनता है। अनुभूति कल्पना और संवेदना के साथ मिलकर रचनाकार को लिखने के लिए आंतरिक रूप से विवश करती है। इसलिए सच्ची रचना प्रत्यक्ष अनुभव से नहीं, बल्कि आंतरिक अनुभूति से जन्म लेती है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अनुभव और अनुभूति में सूक्ष्म अंतर का प्रतिपादन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आंतरिक संवेदना द्वारा सृजन-प्रेरणा का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch15-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">लेखक ने अपने आपको हिरोशिमा के विस्फोट का भोक्ता कब और किस तरह महसूस किया?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक जब जापान के हिरोशिमा नगर में गया, तो उसने अस्पताल में रेडियम से झुलसे लोगों को देखा, किंतु तब वह केवल एक बौद्धिक दर्शक था।</p>\n          <p>किंतु एक दिन सड़क पर घूमते हुए उसने जले हुए एक पत्थर पर एक मानव की काली छाया अंकित देखी। उस समय लेखक के मन में वह दृश्य कौंध गया—परमाणु विस्फोट के समय कोई व्यक्ति उस पत्थर पर खड़ा रहा होगा और रेडियोधर्मी किरणों की भीषण भाप ने उस व्यक्ति को भाप बनाकर उड़ा दिया और उसकी छाया पत्थर पर स्थायी रूप से झुलसा दी। इस दृश्य ने लेखक के हृदय को झकझोर दिया और वह स्वयं को हिरोशिमा के विस्फोट का प्रत्यक्ष भोक्ता अनुभव करने लगा।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पत्थर पर मानव छाया देखने की घटना का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संवेदना द्वारा आंतरिक भोक्ता बनने की प्रक्रिया</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch15-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">'मैं क्यों लिखता हूँ?' के आधार पर बताइए कि लेखक को कौन-सी बातें लिखने के लिए प्रेरित करती हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के अनुसार लिखने की प्रेरणा के दो मुख्य स्रोत होते हैं:</p>\n          <ul>\n            <li><strong>आंतरिक विवशता (मुख्य प्रेरणा):</strong> अपने भीतर की मानसिक छटपटाहट और भावों को अभिव्यक्त कर उनसे मुक्ति पाना तथा स्वयं को जानना (आत्म-साक्षात्कार)।</li>\n            <li><strong>बाह्य दबाव (गौण प्रेरणा):</strong> संपादकों का आग्रह, प्रकाशक का तकाज़ा, प्रशंसकों की माँग तथा कभी-कभी आर्थिक आवश्यकताएँ भी लेखक को लिखने के लिए प्रेरित करती हैं। किंतु सच्चा साहित्य आंतरिक अनुभूति से ही उपजता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आंतरिक विवशता व आत्म-साक्षात्कार का बिंदु</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाह्य दबाव (संपादक, आर्थिक) का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> अज्ञेय जी ने हिरोशिमा पर कविता भारत लौटकर रेलगाड़ी में बैठे-बैठे लिखी थी, हिरोशिमा में नहीं।<br>\n        <strong>कारण (R):</strong> सच्चा साहित्य केवल बाह्य घटना के समय नहीं, बल्कि जब वह घटना स्मृति और आंतरिक अनुभूति में परिपक्व हो जाती है, तब सृजित होता है।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> लेखक ने स्वयं स्वीकार किया कि जब वह अनुभव उनके भीतर एक आर्तनाद बनकर फूटा, तब भारत में रेल के डिब्बे में उन्होंने वह कविता लिखी। अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n  </div>\n</section>","16":"<section class=\"chapter-section\" id=\"ch16\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">16</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 1</div>\n      <h2>बड़े भाई साहब</h2>\n      <p>प्रेमचंद | मनोवैज्ञानिक कहानी — शिक्षा प्रणाली पर व्यंग्य, रटंत विद्या बनाम व्यावहारिक अनुभव और भ्रातृ-प्रेम | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch16-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">छोटे भाई ने अपनी पढ़ाई और खेलकूद के बीच किस प्रकार का टाइम-टेबल बनाया और उसका क्या परिणाम हुआ?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>टाइम-टेबल का निर्माण:</strong> बड़े भाई साहब की डाँट-फटकार सुनकर छोटे भाई ने पढ़ाई के लिए एक अत्यंत कठोर समय-सारणी बनाई, जिसमें सुबह 6 बजे से रात 11 बजे तक हर विषय (अंग्रेजी, गणित, इतिहास आदि) के लिए समय निर्धारित था। किंतु उस टाइम-टेबल में खेलकूद के लिए एक मिनट का भी समय नहीं रखा गया था।</p>\n          <p><strong>परिणाम:</strong> टाइम-टेबल बनाना अलग बात है और उस पर अमल करना दूसरी। खेल के मैदान की सुखद हरियाली, फुटबॉल की उछल-कूद और कबड्डी के दाँव-पेंच उसे बरबस खींच ले जाते थे। पहले ही दिन से टाइम-टेबल की धज्जियाँ उड़ने लगीं और वह उसका पालन नहीं कर सका।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कठोर समय-सारणी व खेल के अभाव का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मैदान के आकर्षण व क्रियान्वयन की विफलता का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch16-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">बड़े भाई साहब दिमाग को आराम देने के लिए क्या-क्या करते थे?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>बड़े भाई साहब दिन-रात लगातार पढ़ते रहते थे। जब उनका दिमाग थक जाता था, तो वे अपनी कॉपियों और किताबों के हाशियों पर चिड़ियों, कुत्तों और बिल्लियों की तस्वीरें बनाते थे। कभी-कभी वे एक ही शब्द या नाम को दस-बीस बार लिखते थे या ऐसे बेमेल शेरों और तुकबंदियों की रचना करते थे जिनका कोई सिर-पैर नहीं होता था।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कॉपियों पर जानवरों के चित्र बनाना</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निरर्थक शब्दों की तुकबंदियाँ व पुनरावृत्ति</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch16-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">बड़े भाई साहब की डाँट-फटकार अगर न मिलती, तो क्या छोटा भाई कक्षा में अव्वल आता? अपने विचार दीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>छोटा भाई स्वाभाविक रूप से कुशाग्र बुद्धि का था, किंतु वह खेलकूद में अधिक मस्त रहता था। यदि बड़े भाई साहब की कड़ी निगरानी, डाँट-फटकार और नैतिक अंकुश न होता, तो वह पढ़ाई के प्रति लापरवाह हो जाता और अपनी प्रतिभा को व्यर्थ गँवा बैठता।</p>\n          <p>बड़े भाई साहब का भय ही था जो उसे खेल से वापस खींचकर पढ़ने की मेज पर लाता था। अतः यह निश्चित है कि छोटे भाई के कक्षा में अव्वल आने में बड़े भाई साहब की सतर्कता और डाँट-फटकार की अत्यंत निर्णायक भूमिका थी।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">छोटे भाई की चंचलता व खेलप्रियता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बड़े भाई के अंकुश व मार्गदर्शन का सकारात्मक प्रभाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch16-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">बड़े भाई साहब पाठ में लेखक ने समूची शिक्षा प्रणाली पर क्या तीखा व्यंग्य किया है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>प्रेमचंद जी ने तत्कालीन औपनिवेशिक शिक्षा व्यवस्था की विसंगतियों पर गंभीर कटाक्ष किया है:</p>\n          <ul>\n            <li><strong>रटंत विद्या पर जोर:</strong> शिक्षा प्रणाली विद्यार्थियों को जीवन की व्यावहारिक सूझबूझ देने के बजाय अंधी रटाई पर मजबूर करती है (जैसे—ज्यामिति में 'अ ब ज' की जगह 'अ ज ब' लिखने पर शून्य अंक देना, दर्जनों हेनरी और जेम्स के इतिहास को रटना)।</li>\n            <li><strong>अव्यावहारिक पाठ्यक्रम:</strong> समय की पाबंदी पर चार पन्नों का निबंध लिखने को कहा जाता है और साथ ही यह भी कहा जाता है कि संक्षेप में लिखो। यह विरोधाभासी है।</li>\n            <li><strong>डिग्री बनाम व्यावहारिक बुद्धि:</strong> लेखक दर्शाते हैं कि किताबें रटने से केवल परीक्षा पास की जा सकती है, किंतु जीवन जीने की वास्तविक बुद्धि और तजुर्बा दुनिया को देखने और बुजुर्गों के अनुभवों से मिलता है (जैसे—अम्मा और दादा का उदाहरण)।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रटंत प्रणाली व ज्यामिति/इतिहास के उदाहरण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">किताबी ज्ञान बनाम व्यावहारिक अनुभव का वैचारिक विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: केस-आधारित चरित्र विश्लेषण (Character Competency)</div>\n      <div class=\"cbq-question\">\n        \"मैं तुमसे पाँच साल बड़ा हूँ और हमेशा रहूँगा। मुझे दुनिया का और जिंदगी का जो तजुर्बा है, तुम उसकी बराबरी नहीं कर सकते।\" बड़े भाई साहब के इस कथन के आलोक में स्पष्ट कीजिए कि क्या केवल परीक्षा में पास होना ही वास्तविक योग्यता का पैमाना है?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        नहीं, केवल परीक्षा में उत्तीर्ण होकर डिग्री हासिल कर लेना वास्तविक योग्यता का प्रमाण नहीं है। किताबी ज्ञान हमें केवल सूचनाएँ देता है, जबकि जीवन का यथार्थ अनुभव, संकटों से जूझने का सामर्थ्य, व्यावहारिक विवेक और नैतिक मूल्य बुजुर्गों के अनुभवों से आते हैं। बड़े भाई साहब फेल होने के बाद भी अपने जीवन-तजुर्बे और बड़प्पन के कारण छोटे भाई के सच्चे मार्गदर्शक बने रहते हैं।\n      </div>\n    </div>\n  </div>\n</section>","17":"<section class=\"chapter-section\" id=\"ch17\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">17</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 2</div>\n      <h2>डायरी का एक पन्ना</h2>\n      <p>सीताराम सेकसरिया | दैनंदिनी — 26 जनवरी 1931, कोलकाता में स्वतंत्रता दिवस उत्सव, पुलिस दमन और नारी शक्ति | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch17-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">26 जनवरी 1931 के दिन को अमर बनाने के लिए क्या-क्या तैयारियाँ की गईं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कोलकाता में 26 जनवरी 1931 को प्रथम स्वतंत्रता दिवस की वर्षगाँठ मनाने के लिए अभूतपूर्व तैयारियाँ की गईं:</p>\n          <ul>\n            <li>प्रचार-प्रसार पर केवल दो हजार रुपये खर्च किए गए और घर-घर जाकर लोगों को समझाया गया।</li>\n            <li>शहर के अधिकांश मकानों पर राष्ट्रीय ध्वज फहराया गया और कई मकानों को इस तरह सजाया गया मानो स्वतंत्रता मिल चुकी हो।</li>\n            <li>बड़ा बाज़ार के प्रायः सभी मकानों पर तिरंगा लहरा रहा था। कलकत्ता के प्रत्येक भाग में झंडे लगाए गए थे और जन-जन में भारी उत्साह था।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रचार-प्रसार व जन-संपर्क का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मकानों पर ध्वजारोहण व सजावट का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch17-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">सुभाष बाबू के जुलूस में स्त्री समाज की क्या भूमिका रही?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>सुभाष चंद्र बोस के इस ऐतिहासिक आंदोलन में नारी शक्ति ने अभूतपूर्व शौर्य और त्याग का प्रदर्शन किया:</p>\n          <ul>\n            <li>सैकड़ों स्त्रियाँ पुलिस की लाठियों और घुड़सवार पुलिस के घेरे की परवाह किए बिना मोनुमेंट की सीढ़ियों पर चढ़ गईं और राष्ट्रीय झंडा फहरा दिया।</li>\n            <li>जानकी देवी, मदालसा जैसी प्रमुख महिलाओं ने जुलूस का नेतृत्व किया और लाठीचार्ज के बावजूद डटी रहीं।</li>\n            <li>लगभग 105 स्त्रियों को गिरफ्तार करके लालबाजार लॉकअप भेजा गया। भारतीय स्वाधीनता संग्राम में महिलाओं की इतनी बड़ी और निर्भीक भागीदारी कोलकाता में पहली बार देखी गई।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मोनुमेंट पर झंडा फहराने व लाठीचार्ज सहने का शौर्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामूहिक गिरफ्तारी व ऐतिहासिक नारी चेतना का प्रभाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch17-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">'कलकत्ता के नाम पर कलंक था कि यहाँ काम नहीं हो रहा है'—उस कलंक को किस प्रकार धो दिया गया?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>देशभर में यह आम धारणा बन गई थी कि स्वतंत्रता आंदोलन में कलकत्ता (बंगाल) के लोग बहुत कम योगदान दे रहे हैं।</p>\n          <p>किंतु 26 जनवरी 1931 को जिस प्रकार बंगाल और मारवाड़ी समाज के पुरुषों और विशेषकर महिलाओं ने पुलिस कमिश्नर के नोटिस की अवहेलना करते हुए पुलिस की बर्बर लाठियाँ सहीं, खून बहाया और जेलों को भर दिया, उसने यह सिद्ध कर दिया कि कलकत्ता किसी से पीछे नहीं है। इस सामूहिक बलिदान और अभूतपूर्व क्रांति ने कलकत्ता के माथे पर लगे उस कलंक को पूरी तरह धो दिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कलकत्ता पर लगे कथित कलंक का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामूहिक त्याग, लाठीचार्ज व जेल भरो द्वारा कलंक मिटाने का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: ऐतिहासिक दस्तावेज़ीकरण (Competency Question)</div>\n      <div class=\"cbq-question\">\n        डायरी विधा की क्या विशेषताएँ होती हैं? 'डायरी का एक पन्ना' पाठ किस प्रकार इतिहास का एक सजीव और विश्वसनीय साक्ष्य प्रस्तुत करता है?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        डायरी विधा में लेखक प्रतिदिन की घटनाओं को अपनी निजी अनुभूति, यथार्थपरक दृष्टि और तात्कालिक प्रभाव के साथ दर्ज करता है। इसमें कोई बनावटीपन या बाद में गढ़ा गया इतिहास नहीं होता। सीताराम सेकसरिया स्वयं इस आंदोलन के प्रत्यक्षदर्शी और सक्रिय सहभागी थे। उनके द्वारा दर्ज किया गया समय, स्थान, लाठीचार्ज की क्रूरता और स्त्रियों की गिरफ्तारी का ब्यौरा इसे स्वतंत्रता संग्राम का एक जीवंत, प्रामाणिक और ऐतिहासिक दस्तावेज बनाता है।\n      </div>\n    </div>\n  </div>\n</section>","18":"<section class=\"chapter-section\" id=\"ch18\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">18</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 3</div>\n      <h2>तताँरा-वामीरो कथा</h2>\n      <p>लीलाधर मंडलोई | लोककथा — अंडमान-निकोबार द्वीप समूह, रूढ़िवादी परंपराओं का विरोध, प्रेम की पावनता और बलिदान | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch18-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">तताँरा की तलवार के बारे में लोगों का क्या मत था?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>तताँरा अपनी कमर में सदैव लकड़ी की एक तलवार बाँधे रहता था। यद्यपि वह लकड़ी की तलवार थी, फिर भी लोगों का यह दृढ़ विश्वास था कि उस तलवार में कोई विलक्षण दैवीय और अद्भुत शक्ति है। तताँरा उस तलवार को कभी किसी के सामने म्यान से बाहर नहीं निकालता था, किंतु उसके साहसिक कारनामों के कारण लोग उस तलवार को चमत्कारी मानते थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लकड़ी की तलवार और दैवीय शक्ति के लोक-विश्वास का उल्लेख</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch18-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">तताँरा और वामीरो के विवाह में क्या मुख्य अड़चन थी?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>तताँरा और वामीरो के विवाह में द्वीप की प्राचीन रूढ़िवादी सामाजिक परंपरा सबसे बड़ी बाधा थी:</p>\n          <ul>\n            <li>नियम के अनुसार विवाह केवल उसी युवक-युवती के बीच हो सकता था जो एक ही गाँव के रहने वाले हों। दूसरे गाँव के युवक से विवाह संबंध पूर्णतः वर्जित था।</li>\n            <li>तताँरा 'पासा' गाँव का रहने वाला था, जबकि वामीरो 'लपाती' गाँव की थी। दोनों अलग-अलग गाँवों के होने के कारण सामाजिक रीति-रिवाजों के अनुसार उनका विवाह असंभव था।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">एक ही गाँव में विवाह की रूढ़िवादी परंपरा का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तताँरा और वामीरो के भिन्न गाँवों (पासा व लपाती) का संदर्भ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch18-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">रूढ़ियाँ जब बंधन बन बोझ बनने लगें, तब उनका टूट जाना ही अच्छा है। क्यों? स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>यह कथन पूर्णतया युक्तिसंगत और सामयिक है:</p>\n          <ul>\n            <li><strong>परंपराओं का मूल उद्देश्य:</strong> सामाजिक नियम और परंपराएँ मनुष्य की सुरक्षा, सुव्यवस्था और कल्याण के लिए बनाई जाती हैं; न कि मनुष्य नियमों के लिए बना है।</li>\n            <li><strong>विकास में बाधक:</strong> जब कोई परंपरा समय के साथ अप्रासंगिक हो जाए और मानवीय संवेदना, प्रेम तथा प्रगति के मार्ग में रोड़ा बनकर लोगों का जीवन छीनने लगे, तो वह परंपरा न रहकर एक अमानवीय 'रूढ़ि' बन जाती है।</li>\n            <li><strong>बलिदान से परिवर्तन:</strong> तताँरा और वामीरो के दुखद आत्म-बलिदान ने समाज की आँखें खोल दीं। निकोबारियों ने उस संकीर्ण गाँव-विवाह प्रथा को समाप्त कर दिया और दूसरे गाँवों में भी वैवाहिक संबंध स्वीकार किए जाने लगे। यदि रूढ़ियाँ न टूटें तो समाज जड़ और गतिहीन होकर नष्ट हो जाता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परंपरा बनाम रूढ़ि के अंतर का दार्शनिक विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तताँरा-वामीरो के बलिदान से आए सामाजिक सुधार का उदाहरण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> तताँरा और वामीरो की मृत्यु व्यर्थ नहीं गई, उसने एक नए समाज की नींव रखी।<br>\n        <strong>कारण (R):</strong> उनके त्याग के पश्चात निकोबार के लोगों ने पुरानी संकीर्ण परंपरा को त्यागकर दूसरे गाँवों में वैवाहिक संबंध बनाना प्रारंभ कर दिया।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> तताँरा-वामीरो के दुखद अंत ने समाज की जड़ता को तोड़ा और सामाजिक नियमों में क्रांतिकारी परिवर्तन आया। अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n  </div>\n</section>","19":"<section class=\"chapter-section\" id=\"ch19\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">19</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 4</div>\n      <h2>तीसरी कसम के शिल्पकार शैलेंद्र</h2>\n      <p>प्रहलाद अग्रवाल | समीक्षात्मक निबंध — गीतकार शैलेंद्र, कलात्मक निष्ठा बनाम व्यावसायिकता, फणीश्वरनाथ 'रेणु' की अमर कृति | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch19-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch19-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">'तीसरी कसम' फिल्म को 'सैल्यूलाइड पर लिखी गई कविता' क्यों कहा गया है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>'तीसरी कसम' केवल मनोरंजन या व्यावसायिक लाभ के लिए बनाई गई फिल्म नहीं थी, बल्कि वह कैमरे के पर्दे (सैल्यूलाइड) पर उकेरी गई विशुद्ध मानवीय संवेदना की कविता थी:</p>\n          <ul>\n            <li>इसमें ग्रामीण अंचल की निश्छलता, हीरामन गाड़ीवान की मासूमियत और हीराबाई की आंतरिक विवशता का अत्यंत सूक्ष्म और काव्यात्मक चित्रण था।</li>\n            <li>फिल्म में कोई सस्ता तड़क-भड़क या नकली ड्रामा नहीं था; उसका प्रत्येक दृश्य एक संवेदनशील कविता के छंद की तरह दर्शक के हृदय को छू जाता था।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यावसायिकता से परे मानवीय संवेदना का चित्रण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सैल्यूलाइड पर काव्यात्मक अनुभूति का साकार रूप</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch19-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch19-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">शैलेंद्र ने राजकपूर की किन-किन विशेषताओं को अपनी फिल्म में उतारा?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>शैलेंद्र ने राजकपूर के भीतर छिपे विशुद्ध अभिनेता को पहचाना और 'हीरामन' के रूप में उन्हें प्रस्तुत किया:</p>\n          <ul>\n            <li>राजकपूर को एशिया का सबसे बड़ा शोमैन माना जाता था, किंतु शैलेंद्र ने उनके इस ग्लैमर को उतारकर उन्हें एक सीधा-सादा, देहाती और निश्छल गाड़ीवान बनाया।</li>\n            <li>राजकपूर ने हीरामन के किरदार में मासूमियत, बाल-सुलभ लज्जा और आँखों से प्रेम अभिव्यक्त करने का अद्वितीय अभिनय किया, जो उनके जीवन की सर्वश्रेष्ठ भूमिका बन गई।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शोमैन के चोले से निकालकर विशुद्ध अभिनेता की पहचान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हीरामन के किरदार में जीवंत देहाती अभिनय की प्रस्तुति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch19-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch19-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">शैलेंद्र एक आदर्शवादी भावुक कवि थे, सफल व्यापारी नहीं—स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>शैलेंद्र की आत्मा एक सच्चे कवि और कलाकार की थी, जो लाभ-हानि के सांसारिक तराजू पर नहीं तौली जा सकती:</p>\n          <ul>\n            <li>जब राजकपूर ने उन्हें फिल्म निर्माण के वित्तीय जोखिमों और पैसे डूबने की चेतावनी दी, तो शैलेंद्र ने हँसते हुए कहा कि वे फिल्म पैसे कमाने के लिए नहीं, बल्कि साहित्य और कला की सच्ची सेवा के लिए बना रहे हैं।</li>\n            <li>वे फिल्म वितरकों के आगे नहीं झुके और न ही बाजारू मांग के अनुसार फिल्म में सस्ते फार्मूले जोड़े। इस कलात्मक निष्ठा के कारण फिल्म को राष्ट्रपति का स्वर्ण पदक तो मिला, किंतु शैलेंद्र आर्थिक रूप से बर्बाद हो गए और मानसिक आघात से असमय संसार से विदा हो गए।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यावसायिक मुनाफे के स्थान पर कलात्मक निष्ठा को प्राथमिकता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वित्तीय कठिनाइयों व समझौते न करने का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: सिनेमा और साहित्य का अंतर्संबंध (Competency Question)</div>\n      <div class=\"cbq-question\">\n        आज के व्यावसायिक सिनेमा में साहित्य और मानवीय मूल्यों का अभाव क्यों दिखाई देता है? शैलेंद्र की 'तीसरी कसम' वर्तमान फिल्मकारों को क्या संदेश देती है?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        आज का सिनेमा मुख्यतः करोड़ों रुपये के बॉक्स-ऑफिस कलेक्शन, हिंसा और तड़क-भड़क पर केंद्रित हो चुका है, जिससे उसमें आत्मा और साहित्यिक गहराई खो गई है। शैलेंद्र की 'तीसरी कसम' यह अमर संदेश देती है कि महान कला वही है जो मानवीय करुणा, निश्छल प्रेम और मिट्टी की महक से जुड़ी हो। बॉक्स ऑफिस की तात्कालिक सफलता से परे कालजयी कला वही बनती है जो दर्शकों के हृदय को झकझोर दे।\n      </div>\n    </div>\n  </div>\n</section>","20":"<section class=\"chapter-section\" id=\"ch20\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">20</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 5</div>\n      <h2>अब कहाँ दूसरे के दुख से दुखी होने वाले</h2>\n      <p>निदा फ़ाज़ली | आत्मकथात्मक निबंध — पर्यावरण असंतुलन, मानवेतर प्राणियों के प्रति संवेदनहीनता, कंक्रीट के जंगल और सह-अस्तित्व | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch20-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch20-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">अरब में लशकर को 'नूह' के नाम से क्यों याद किया जाता है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>अरब में पैगंबर लशकर को 'नूह' (अर्थात अत्यधिक विलाप करने या रोने वाला) के नाम से इसलिए याद किया जाता है क्योंकि वे जीवन भर एक घायल कुत्ते के प्रति कहे गए अपने कटु वचन के पश्चाताप में रोते रहे।</p>\n          <p>एक बार उन्होंने एक जख्मी कुत्ते को देखकर घृणा से दुत्कार दिया था। कुत्ते ने उत्तर दिया—\"न मैं अपनी मर्जी से कुत्ता हूँ, न तुम अपनी पसंद से इंसान हो। बनाने वाला हम दोनों का वही एक ईश्वर है।\" कुत्ते की इस आध्यात्मिक बात ने नूह के दिल को बींध दिया और वे जीवन भर अपनी भूल पर आँसू बहाते रहे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'नूह' शब्द का अर्थ (विलाप करने वाला)</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कुत्ते द्वारा दिए गए उत्तर व नूह के आजीवन पश्चाताप का उल्लेख</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch20-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch20-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">प्रकृति में आए असंतुलन का क्या दुष्परिणाम हुआ है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मनुष्य ने अपनी स्वार्थपरता और अंधी तृष्णा के कारण प्रकृति के साथ भीषण छेड़छाड़ की है, जिसके विनाशकारी परिणाम सामने आ रहे हैं:</p>\n          <ul>\n            <li><strong>प्राकृतिक आपदाओं का प्रकोप:</strong> बेमौसम की भारी बरसात, भयानक तूफान, चक्रवात, सुनामी और भूकंप की घटनाओं में निरंतर वृद्धि।</li>\n            <li><strong>ऋतु-चक्र का बिगड़ना:</strong> अत्यधिक गर्मी, घटती ठंड और जल-संकट।</li>\n            <li><strong>नई बीमारियाँ:</strong> पर्यावरण प्रदूषण के कारण मानव जीवन में नित नए प्राणघातक रोगों का जन्म। समुद्र और प्रकृति का गुस्सा सुनामी बनकर इंसानों और जहाजों को तिनकों की तरह फेंक रहा है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बेमौसम बरसात, तूफान, सुनामी व भूकंप का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ऋतु-असंतुलन व नई महामारियों का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch20-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch20-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लेखक की माँ ने कबूतर का अंडा टूट जाने पर क्या प्रायश्चित किया?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के घर में रोशनदान में कबूतर के दो अंडे थे। एक अंडा बिल्ली ने फोड़ दिया था। जब लेखक की माँ दूसरे अंडे को सुरक्षित रखने के लिए स्टूल पर चढ़ीं, तो उनके हाथ से फिसलकर दूसरा अंडा भी फर्श पर गिरकर फूट गया।</p>\n          <p>कबूतर के जोड़े को तड़पते और फड़फड़ाते देखकर माँ की आँखों में आँसू आ गए। इस अनजाने में हुए पाप का प्रायश्चित करने के लिए माँ ने पूरे दिन का रोज़ा रखा, दिन भर न कुछ खाया न पिया, और नमाज़ पढ़कर रो-रोकर खुदा से अपने इस गुनाह की माफी माँगती रहीं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अंडा टूटने की घटना और कबूतरों के विलाप का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दिन भर रोज़ा रखकर पश्चाताप व नमाज़ में माफी माँगने का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: केस-आधारित पर्यावरण नीतिशास्त्र (Environmental Ethics)</div>\n      <div class=\"cbq-question\">\n        \"डेरा डालने का मतलब है कि कुछ समय के लिए रहना, लेकिन आज पक्षियों और जानवरों के लिए धरती पर कोई स्थायी ठिकाना नहीं बचा।\" आधुनिक कंक्रीट के विकास और वन्यजीवों के बेघर होने पर एक विचारपरक टिप्पणी लिखिए।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        यह धरती केवल मनुष्य की निजी जागीर नहीं है, बल्कि इस पर पेड़-पौधों, पशु-पक्षियों और सूक्ष्म जीवों का भी बराबर का अधिकार है। मनुष्य ने जंगलों को काटकर और समुद्र को पीछे धकेलकर कंक्रीट की गगनचुंबी इमारतें खड़ी कर दी हैं। परिणामतः पक्षी अपने घोंसले खोकर फ्लैटों की जालियों और छज्जों पर फड़फड़ा रहे हैं। यदि हमने इस जैव-विविधता और सह-अस्तित्व की रक्षा नहीं की, तो पर्यावरण का यह महाविनाश स्वयं मनुष्य के अस्तित्व को भी समाप्त कर देगा।\n      </div>\n    </div>\n  </div>\n</section>","21":"<section class=\"chapter-section\" id=\"ch21\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">21</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 6</div>\n      <h2>पतझर में टूटी पत्तियाँ</h2>\n      <p>रवींद्र केलेकर | निबंध — (1) गिन्नी का सोना (आदर्शवाद बनाम व्यावहारिकता) (2) झेन की देन (टी-सेरेमनी, वर्तमान में जीना, मानसिक शांति) | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch21-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch21-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">'शुद्ध सोना' और 'गिन्नी के सोने' में क्या अंतर है? लेखक ने इसके माध्यम से क्या विचार व्यक्त किया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>अंतर:</strong> 'शुद्ध सोना' 100% खरा होता है, जिसमें कोई मिलावट नहीं होती। किंतु 'गिन्नी का सोना' वह होता है जिसमें थोड़ा ताँबा मिलाया जाता है ताकि वह अधिक चमकदार और मजबूत बने तथा उससे आभूषण गढ़े जा सकें।</p>\n          <p><strong>लेखक का विचार:</strong> लेखक ने इसके माध्यम से 'शुद्ध आदर्श' और 'व्यावहारिकता' के द्वंद्व को स्पष्ट किया है। विशुद्ध आदर्शवादी व्यक्ति शुद्ध सोने जैसे होते हैं, जो कभी अपने नैतिक मूल्यों से समझौता नहीं करते (जैसे गांधी जी)। जबकि अवसरवादी लोग आदर्शों में स्वार्थ और व्यावहारिकता का ताँबा मिलाकर केवल अपना लाभ साधते हैं। समाज को शाश्वत दिशा शुद्ध आदर्शवादी ही देते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध सोने और गिन्नी के सोने में ताँबे की मिलावट का अंतर</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध आदर्शवादी बनाम व्यावहारिक अवसरवादिता का रूपक</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch21-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch21-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">जापान में 'टी-सेरेमनी' (चा-नो-यू) क्या है और इसमें मानसिक शांति कैसे प्राप्त होती है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>जापान में चाय पीने की एक अत्यंत विशिष्ट और ध्यानमग्न पारंपरिक विधि है, जिसे 'चा-नो-यू' (टी-सेरेमनी) कहते हैं:</p>\n          <ul>\n            <li>यह एक शांत पर्णकुटी में आयोजित की जाती है, जहाँ एक बार में केवल तीन व्यक्तियों को प्रवेश मिलता है ताकि शांति भंग न हो।</li>\n            <li>वहाँ चाय तैयार करने वाले (चाजीन) की प्रत्येक चेष्टा, पानी का उबलना, चाय का छनना अत्यंत धीमी और गरिमामय गति से होता है।</li>\n            <li>आधा प्याला चाय को घूँट-घूँट कर डेढ़-दो घंटे तक शांत वातावरण में पिया जाता है। इस मूक और तनावमुक्त प्रक्रिया से मन के विचार शून्य हो जाते हैं और व्यक्ति वर्तमान के पल में जीने का असीम आनंद अनुभव करता है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'चा-नो-यू' विधि और शांत पर्णकुटी के वातावरण का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घूँट-घूँट पीने से वर्तमान में जीने व विचार शून्यता का लाभ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch21-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch21-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लेखक के अनुसार वास्तविक सत्य क्या है—भूतकाल, भविष्यकाल या वर्तमानकाल?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>लेखक के अनुसार भूतकाल बीत चुका है, जो अब मिथ्या है; और भविष्यकाल अभी आया नहीं है, जो केवल एक कल्पना है। मनुष्य इन दोनों कालों की चिंताओं में उलझकर अपने जीवन को तनावग्रस्त कर लेता है।</p>\n          <p>वास्तविक सत्य केवल 'वर्तमान काल' है, जो इस क्षण हमारे सम्मुख उपस्थित है। जो व्यक्ति वर्तमान के प्रत्येक पल को पूरी तन्मयता, शांति और जागरूकता के साथ जीता है, वही वास्तव में जीवन के अमृत और शाश्वत सत्य का साक्षात्कार करता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भूतकाल की अप्रासंगिकता व भविष्य की काल्पनिकता का तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वर्तमान क्षण को ही एकमात्र यथार्थ व शाश्वत सत्य मानना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> जापान में मानसिक रोगियों की संख्या अन्य देशों की तुलना में काफी अधिक है।<br>\n        <strong>कारण (R):</strong> वहाँ का जीवन अत्यधिक तीव्र गति से चलता है और लोग एक महीने का काम एक दिन में पूरा करने की अंधी प्रतिस्पर्द्धा में लगे रहते हैं, जिससे दिमाग का इंजन टूट जाता है।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> अत्यधिक मानसिक तनाव और अमेरिका से होड़ के चक्कर में तेज रफ्तार जिंदगी ने जापानी लोगों को अवसाद और मानसिक रोगों की ओर धकेल दिया है। अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n  </div>\n</section>","22":"<section class=\"chapter-section\" id=\"ch22\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">22</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (गद्य खंड) — पाठ 7</div>\n      <h2>कारतूस</h2>\n      <p>हबीब तनवीर | एकांकी — वज़ीर अली का अदम्य साहस, अंग्रेजों के विरुद्ध बगावत, देशभक्ति और चतुरंग कूटनीति | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch22-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch22-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कर्नल कालिंज का खेमा जंगल में क्यों लगा हुआ था?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कर्नल कालिंज अपनी पूरी फौज और लेफ्टिनेंट के साथ गोरखपुर के जंगलों में कई हफ्तों से डेरा डाले हुए था। उसका एकमात्र उद्देश्य अवध के पूर्व नवाब और विद्रोही जाँबाज वज़ीर अली को जिंदा या मुर्दा पकड़ना था, जो अंग्रेजों की नाक में दम किए हुए था और जंगलों में छिपकर अपनी सैन्य शक्ति संगठित कर रहा था।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वज़ीर अली को गिरफ्तार करने के उद्देश्य का स्पष्ट उल्लेख</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch22-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch22-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">वज़ीर अली ने कंपनी के वकील का कत्ल क्यों किया?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>जब अंग्रेजों ने वज़ीर अली को अवध के तख्त से हटाकर बनारस भेज दिया और फिर गवर्नर जनरल ने उसे कलकत्ता तलब किया, तो वज़ीर अली बनारस में रहने वाले कंपनी के वकील के पास शिकायत लेकर गया।</p>\n          <p>वकील ने वज़ीर अली की न्यायसंगत शिकायत सुनने के बजाय उसे बुरी तरह खरी-खोटी सुनाई और उसका अपमान किया। वज़ीर अली के स्वाभिमानी और विद्रोही खून ने इस अपमान को सहन नहीं किया। उसने तुरंत अपनी म्यान से खंजर निकाला और उस धृष्ट वकील का काम तमाम कर दिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कंपनी के वकील द्वारा अपमानित व दुर्व्यवहार करने का कारण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वज़ीर अली के स्वाभिमान व खंजर से वध करने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch22-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch22-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">सवार ने कर्नल से कारतूस कैसे हासिल किए और कर्नल हक्का-बक्का क्यों रह गया?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>कारतूस हासिल करना:</strong> वज़ीर अली स्वयं एक घुड़सवार के भेष में अकेले कर्नल के खेमे में घुस आया। उसने कर्नल से एकांत में बात करने की माँग की और कहा कि वह भी वज़ीर अली को गिरफ्तार करवाने आया है। उसने बहाना बनाया कि वज़ीर अली को पकड़ने के लिए उसे कुछ कारतूसों की सख्त जरूरत है। कर्नल खुश होकर उसे तुरंत दस कारतूस दे देता है।</p>\n          <p><strong>कर्नल का हक्का-बक्का रहना:</strong> जब कर्नल ने जाने से पहले उसका नाम पूछा, तो सवार ने अत्यंत निर्भीकता से कहा—\"वज़ीर अली! आपने मुझे कारतूस दिए हैं, इसलिए आपकी जान बख्शता हूँ!\" यह कहकर वह बिजली की तेजी से अपने घोड़े पर सवार होकर गायब हो गया। शेर की मांद में घुसकर उसी के हाथों से कारतूस ले जाने वाले इस जाँबाज की अदम्य वीरता देखकर कर्नल सन्न और हक्का-बक्का रह गया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अकेले खेमे में प्रवेश व कूटनीति से दस कारतूस प्राप्त करना</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नाम का खुलासा, कर्नल की जान बख्शना व विस्मय का प्रभाव</span><span class=\"marking-marks\">2.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: चरित्र मूल्यांकन (Character Competency)</div>\n      <div class=\"cbq-question\">\n        एकांकी के अंत में कर्नल कालिंज द्वारा वज़ीर अली को 'एक जाँबाज सिपाही' कहना शत्रु के प्रति किस प्रकार के सम्मान को दर्शाता है?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        यह कथन सिद्ध करता है कि सच्ची वीरता, स्वाभिमान और अदम्य साहस शत्रु के हृदय में भी आदर की भावना पैदा कर देता है। यद्यपि कर्नल वज़ीर अली का कट्टर विरोधी और उसे गिरफ्तार करने आया ब्रिटिश अफसर था, किंतु वज़ीर अली की निडरता, निर्भयता और अकेले दुश्मनों के शिविर में घुसने के हैरतअंगेज कारनामे ने कर्नल को नतमस्तक कर दिया।\n      </div>\n    </div>\n  </div>\n</section>","23":"<section class=\"chapter-section\" id=\"ch23\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">23</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 1</div>\n      <h2>साखी</h2>\n      <p>संत कबीरदास | सधुक्कड़ी भाषा — नीति, ज्ञान, अहंकार-मुक्ति, नाम-महिमा और भक्ति की साधना | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch23-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">मीठी वाणी बोलने से औरों को सुख और अपने तन को शीतलता कैसे प्राप्त होती है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कबीरदास जी के अनुसार—<em>\"ऐसी बाणी बोलिये, मन का आपा खोइ। औरन को सीतल करै, आपहु सीतल होइ॥\"</em></p>\n          <ul>\n            <li>जब मनुष्य अपने अहंकार (आपा) का त्याग करके मधुर और विनम्र वाणी बोलता है, तो उसके भीतर का क्रोध, कटुता और ईर्ष्या समाप्त हो जाती है, जिससे उसका अपना मन और शरीर शांत (शीतल) हो जाता है।</li>\n            <li>ऐसी वाणी सुनने वाले के हृदय की पीड़ा को हरकर उसे अपार सुख, प्रेम और आत्मीयता प्रदान करती है। मीठे बोल बैर को मिटाकर सौहार्द की सृष्टि करते हैं।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अहंकार त्याग से आत्मिक शीतलता मिलने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">श्रोता के मन पर सुखद व शांतिदायक प्रभाव का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch23-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">ईश्वर कण-कण में व्याप्त है, पर हम उसे क्यों नहीं देख पाते?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कबीरदास जी कस्तूरी मृग का उदाहरण देते हुए कहते हैं—<em>\"कस्तूरी कुंडलि बसै, मृग ढूँढ़ै बन माहि। ऐसे घटि-घटि रांम हैं, दुनियां देखै नांहि॥\"</em></p>\n          <p>जिस प्रकार मृग की अपनी नाभि में ही कस्तूरी की सुगंध होती है, किंतु अज्ञानतावश वह उसे सारे जंगल में ढूँढ़ता फिरता है; उसी प्रकार परमात्मा प्रत्येक मनुष्य के अंतःकरण और सृष्टि के कण-कण में समाया हुआ है। किंतु अज्ञान, मोह-माया और अहंकार के पर्दे के कारण मनुष्य उसे अपने भीतर न देखकर मंदिरों, मस्जिदों और तीर्थों में ढूँढ़ता भटकता रहता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कस्तूरी मृग के दृष्टांत का सटीक प्रयोग</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अज्ञानता व अहंकार द्वारा अंतःकरण के ईश्वर को न देख पाने का कारण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch23-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">अपने स्वभाव को निर्मल रखने के लिए कबीर ने क्या उपाय सुझाया है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कबीरदास जी ने निंदक (आलोचना करने वाले) को अपने सबसे समीप रखने का उपाय सुझाया है—<em>\"निंदक नेड़ा राखिये, आँगण कुटी बँधाइ। बिन साबण पाँणीं बिना, निरमल करै सुभाइ॥\"</em></p>\n          <p>निंदक हमारी त्रुटियों और कमियों को उजागर करता रहता है। उसकी आलोचना को सुनकर हम बिना साबुन और पानी के ही अपने दोषों को सुधार लेते हैं, जिससे हमारा स्वभाव स्वतः निर्मल और पवित्र बन जाता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निंदक को समीप रखने का सुझाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दोषों को सुधारकर स्वभाव निर्मल बनाने की प्रक्रिया</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> कबीर संसार के लोगों को 'सुखिया' और स्वयं को 'दुखिया' मानते हैं।<br>\n        <strong>कारण (R):</strong> संसार भौतिक भोग-विलास में मग्न होकर सो रहा है, जबकि कबीर नश्वरता और ईश्वर वियोग के सत्य को जानकर जागते हुए रो रहे हैं।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> कबीर की दृष्टि में अज्ञानी संसार खाना-पीना और सोने में ही सुख मानता है, किंतु ज्ञानी संत ईश्वर वियोग और संसार की नश्वरता से दुखी रहता है। अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n  </div>\n</section>","24":"<section class=\"chapter-section\" id=\"ch24\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">24</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 2</div>\n      <h2>पद</h2>\n      <p>मीराबाई | राजस्थानी मिश्रित ब्रजभाषा — माधुर्य भाव की भक्ति, दैन्य भाव, अनन्य समर्पण और श्रीकृष्ण के प्रति आर्त पुकार | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch24-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch24-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">पहले पद में मीरा ने हरि से अपनी पीड़ा हरने की विनती किस प्रकार की है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मीराबाई श्रीकृष्ण को उनके भक्तवत्सल रूप की याद दिलाते हुए अपनी पीड़ा हरने की प्रार्थना करती हैं। वे तीन पौराणिक उदाहरण देती हैं:</p>\n          <ol>\n            <li><strong>द्रौपदी की लाज:</strong> जब दुःशासन चीरहरण कर रहा था, तब प्रभु ने वस्त्र बढ़ाकर भरी सभा में उसकी लाज रखी थी।</li>\n            <li><strong>प्रह्लाद की रक्षा:</strong> भक्त प्रह्लाद को बचाने के लिए प्रभु ने नृसिंह रूप धारण कर अहंकारी हिरण्यकश्यप का वध किया था।</li>\n            <li><strong>ऐरावत हाथी का उद्धार:</strong> जब मगरमच्छ ने हाथी को पकड़ लिया था, तब भगवान ने ग्राह को मारकर हाथी की पीड़ा हरी थी।</li>\n          </ol>\n          <p>मीरा कहती हैं कि हे प्रभु! मैं भी आपकी दासी हूँ, इसलिए मेरी भी विरह-पीड़ा और सांसारिक कष्टों को दूर कीजिए।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">द्रौपदी, प्रह्लाद व ऐरावत के प्रसंगों का उल्लेख</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वयं को दासी मानकर आर्त पुकार करने का भाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch24-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch24-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">दूसरे पद में मीराबाई श्याम की चाकरी क्यों करना चाहती हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>मीराबाई श्रीकृष्ण की सेविका (चाकर) बनकर उनके समीप रहना चाहती हैं। चाकरी करने से उन्हें तीन बड़े आध्यात्मिक लाभ प्राप्त होंगे:</p>\n          <ul>\n            <li><strong>नित्य दर्शन:</strong> वे प्रभु के लिए बाग-बगीचे लगाएँगी जिससे रोज सुबह उठते ही उन्हें कृष्ण के दर्शन प्राप्त होंगे।</li>\n            <li><strong>नाम-स्मरण की खर्ची:</strong> वृंदावन की कुंज-गलियों में कृष्ण की लीलाओं के गीत गाएँगी, जिससे उन्हें वेतन के रूप में निरंतर प्रभु के नाम का स्मरण मिलेगा।</li>\n            <li><strong>भाव-भक्ति की जागीर:</strong> भक्ति रूपी असीम संपत्ति (जागीर) प्राप्त होगी, जिससे उनका जीवन धन्य हो जाएगा।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दर्शन, नाम-स्मरण व भाव-भक्ति की जागीर का उल्लेख</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दास्य भाव और सामीप्य की आकांक्षा</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: रूप-सौंदर्य व काव्य-सौंदर्य विश्लेषण (Competency Question)</div>\n      <div class=\"cbq-question\">\n        मीराबाई द्वारा दूसरे पद में श्रीकृष्ण के रूप-सौंदर्य का जो वर्णन किया गया है, उसकी प्रमुख विशेषताओं को रेखांकित कीजिए।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        मीरा ने कृष्ण के नटवर वेश का अत्यंत मोहक चित्र खींचा है:<br>\n        1. उनके शीश पर मोर के पंखों का मुकुट (मोरमुकुट) सुशोभित है।<br>\n        2. उनके अंगों पर पीतांबर (पीले वस्त्र) शोभा पा रहे हैं और गले में वनफूलों की वैजयंती माला विराजमान है।<br>\n        3. वे वृंदावन में मधुर बाँसुरी बजाते हुए गायें चराते हैं। यह रूप साक्षात् सौंदर्य और माधुर्य का सागर है।\n      </div>\n    </div>\n  </div>\n</section>","25":"<section class=\"chapter-section\" id=\"ch25\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">25</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 3</div>\n      <h2>मनुष्यता</h2>\n      <p>राष्ट्रकवि मैथिलीशरण गुप्त | खड़ी बोली — विश्व-बंधुत्व, परोपकार, त्याग, अमरता और सच्ची मानवता का संदेश | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch25-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कवि ने कैसी मृत्यु को 'सुमृत्य' कहा है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि के अनुसार मृत्यु तो सभी जीवों के लिए अनिवार्य और निश्चित है। किंतु 'सुमृत्य' (सार्थक और सुंदर मृत्यु) केवल उसी व्यक्ति की होती है, जो जीते जी परोपकार, समाज सेवा और दूसरों के कल्याण के लिए अपना जीवन समर्पित करता है।</p>\n          <p>ऐसे व्यक्ति के मरने के बाद भी समूचा संसार उसके उपकारों को याद रखता है और श्रद्धा से नमन करता है। जो केवल अपने स्वार्थ के लिए जीता और मरता है, उसका जीना और मरना दोनों व्यर्थ है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परोपकार व समाज कल्याण के लिए जीवन न्योछावर करना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मृत्योपरांत भी संसार द्वारा श्रद्धा से याद किए जाने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch25-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">कवि ने दधीचि, कर्ण और उशीनर आदि का उदाहरण देकर क्या संदेश दिया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि ने इन महान पौराणिक विभूतियों के त्याग के माध्यम से यह संदेश दिया है कि यह नश्वर शरीर क्षणभंगुर है, इसलिए परोपकार के लिए इसे न्योछावर करने में तनिक भी संकोच नहीं करना चाहिए:</p>\n          <ul>\n            <li><strong>महर्षि दधीचि:</strong> देवताओं की रक्षा के लिए अपनी जीवित अस्थियों (हड्डियों) का दान कर दिया।</li>\n            <li><strong>राजा उशीनर (शिवि):</strong> एक शरणागत कबूतर की जान बचाने के लिए अपने शरीर का मांस काटकर बाज को दे दिया।</li>\n            <li><strong>दानवीर कर्ण:</strong> याचक के माँगने पर अपने प्राण रक्षक कुंडल और कवच सहर्ष दान कर दिए।</li>\n          </ul>\n          <p>सच्चा मनुष्य वही है जो दूसरों की भलाई के लिए सर्वस्व त्याग दे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दधीचि, उशीनर व कर्ण के त्याग का स्पष्ट उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नश्वर देह से शाश्वत परोपकार करने की प्रेरणा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch25-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">'मनुष्य मात्र बंधु है' से आप क्या समझते हैं? स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि के अनुसार इस संपूर्ण पृथ्वी पर रहने वाले सभी मनुष्य एक ही परमपिता परमात्मा (ईश्वर) की संतान हैं। अतः जाति, धर्म, वर्ण, देश या भाषा के आधार पर कोई किसी से भिन्न या पराया नहीं है; सभी आपस में सगे भाई (बंधु) हैं।</p>\n          <p>मनुष्य का यह सर्वोच्च कर्तव्य है कि वह दूसरे भाई के दुख-दर्द को अपना समझे, उसके आँसू पोंछे और विपत्ति में उसकी सहायता करे। जो मनुष्य अपने भाई की पीड़ा को नहीं समझता, वह पशु के समान है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">एक ही परमपिता की संतान होने का बोध</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विश्व-बंधुत्व व परस्पर सहानुभूति का कर्तव्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> वही मनुष्य है जो मनुष्य के लिए मरे।<br>\n        <strong>कारण (R):</strong> केवल अपने लिए भोजन और स्वार्थ साधना पशु-प्रवृत्ति है, जबकि दूसरों के हित के लिए जीना-मरना सच्ची मनुष्यता है।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> मैथिलीशरण गुप्त जी ने स्पष्ट कहा है कि पशु केवल अपनी चराई खोजता है, जबकि सच्चा मनुष्य अपने प्राणों की आहुति देकर भी दूसरे मनुष्य की रक्षा करता है। अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n  </div>\n</section>","26":"<section class=\"chapter-section\" id=\"ch26\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">26</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 4</div>\n      <h2>पर्वत प्रदेश में पावस</h2>\n      <p>प्रकृति के सुकुमार कवि सुमित्रानंदन पंत | छायावादी कविता — वर्षा ऋतु, हिमालय का जादुई सौंदर्य, मानवीकरण और कल्पनाशीलता | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch26-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">'सहस्र दृग-सुमन' से क्या तात्पर्य है? कवि ने इस पद का प्रयोग किसके लिए किया है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>तात्पर्य:</strong> 'सहस्र' का अर्थ है हजार, 'दृग' का अर्थ है आँखें और 'सुमन' का अर्थ है फूल। 'सहस्र दृग-सुमन' का अर्थ है—हजारों नेत्र रूपी फूल।</p>\n          <p><strong>प्रयोग:</strong> कवि ने इस पद का प्रयोग पर्वत के लिए किया है। पर्वत के ढलानों पर खिले हुए हजारों रंग-बिरंगे फूल ऐसे प्रतीत होते हैं मानो वे पर्वत की विशाल आँखें हों, जिनके माध्यम से पर्वत नीचे फैले दर्पण जैसे स्वच्छ तालाब में अपने विराट रूप और सौंदर्य को निहार रहा है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शब्दार्थ का सटीक विश्लेषण (हजारों नेत्र रूपी पुष्प)</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पर्वत द्वारा तालाब में अपना रूप निहारने के मानवीकरण का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch26-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">कवि ने तालाब की समानता किसके साथ दिखाई है और क्यों?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि ने पर्वत के चरणों में स्थित तालाब की समानता एक विशाल 'दर्पण' (आईने) के साथ दिखाई है—<em>\"दर्पण-सा फैला है विशाल\"</em>।</p>\n          <p>इसका कारण यह है कि तालाब का जल अत्यंत निर्मल, पारदर्शी और शांत है, जिसमें सामने खड़े गगनचुंबी पर्वत और खिले हुए फूलों का प्रतिबिंब बिल्कुल शीशे की तरह साफ और सुंदर दिखाई दे रहा है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दर्पण के साथ समानता का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जल की स्वच्छता व प्रतिबिंब के कारण तुलना का औचित्य</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch26-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">शाल के वृक्ष भयभीत होकर धरती में क्यों धँस गए प्रतीत होते हैं?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>पावस ऋतु में अचानक आकाश में घने काले बादल छा गए और मूसलाधार बारिश शुरू हो गई मानो आकाश ही टूटकर धरती पर गिर पड़ा हो। चारों ओर धुंध और बादलों का ऐसा सफेद धुआँ उठा कि पर्वत, तालाब और पेड़ सब अदृश्य हो गए।</p>\n          <p>शाल के गगनचुंबी पेड़ धुंध में विलीन होकर गायब हो गए। इस दृश्य को देखकर कवि कल्पना करता है मानो आकाश के भयानक प्रहार और बादलों के आतंक से डरकर शाल के वृक्ष धरती में धँस गए हों।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घनी धुंध और बादलों के आवरण का प्राकृतिक दृश्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भयभीत होकर धरती में समाने की मानवीकृत कल्पना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: छायावादी बिंब-विधान व मानवीकरण (Poetic Imagery)</div>\n      <div class=\"cbq-question\">\n        \"गिरिवर के उर से उठ-उठ कर, उच्चाकांक्षाओं से तरुवर, हैं झाँक रहे नीरव नभ पर, अनिमेश, अटल, कुछ चिंतापर।\" इन पंक्तियों में निहित दार्शनिक भाव और मानवीकरण अलंकार को स्पष्ट कीजिए।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        यहाँ पेड़ों का मानवीकरण ऐसे महत्वाकांक्षी व्यक्तियों के रूप में किया गया है जो जीवन में निरंतर ऊँचाइयों को छूना चाहते हैं। पर्वत की छाती से उगे पेड़ शांत आकाश को एकटक (अनिमेष), स्थिर और चिंतामग्न भाव से देख रहे हैं। यह दृश्य मनुष्य की अनंत ऊँचाइयों को छूने की अदम्य इच्छा और उस लक्ष्य को पाने की आंतरिक बेचैनी का सशक्त प्रतीक है।\n      </div>\n    </div>\n  </div>\n</section>","27":"<section class=\"chapter-section\" id=\"ch27\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">27</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 5</div>\n      <h2>तोप</h2>\n      <p>वीरेन डंगवाल | समकालीन कविता — 1857 की ऐतिहासिक तोप, औपनिवेशिक क्रूरता, समय का परिवर्तन और शक्ति का नश्वर अंत | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch27-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कंपनी बाग में रखी तोप क्या संदेश देती है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कंपनी बाग के मुहाने पर रखी 1857 की तोप हमें दो महत्त्वपूर्ण ऐतिहासिक संदेश देती है:</p>\n          <ol>\n            <li><strong>स्वतंत्रता संग्राम के शहीदों का स्मरण:</strong> यह याद दिलाती है कि हमारे देश के वीर सेनानियों ने किस प्रकार अंग्रेजों के भीषण अत्याचारों और तोपों का सामना करते हुए देश को आजाद कराया।</li>\n            <li><strong>सत्ता और शक्ति की नश्वरता:</strong> यह तोप कभी बड़े-बड़े वीरों के परखच्चे उड़ा देती थी, किंतु आज वह केवल एक खिलौना बनकर रह गई है। यह संदेश देती है कि जुल्म और अहंकार कितना भी बड़ा क्यों न हो, एक दिन उसका अंत अवश्यंभावी है।</li>\n          </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">1857 के शहीदों की कुर्बानियों की याद</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शक्ति और क्रूरता के नश्वर अंत का दार्शनिक संदेश</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch27-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">तोप की वर्तमान स्थिति क्या है? कविता के आधार पर वर्णन कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>आज वह भयानक तोप पूर्णतया शक्तिहीन, मूक और निष्प्रभावी हो चुकी है:</p>\n          <ul>\n            <li>कंपनी बाग में आने वाले छोटे-छोटे बच्चे उसकी पीठ पर बैठकर घुड़सवारी का खेल खेलते हैं।</li>\n            <li>जब बच्चे नहीं होते, तो चिड़ियाँ और गौरैये उसके ऊपर बैठकर आपस में गपशप करते हैं और कभी-कभी बेखौफ होकर उसके मुँह के अंदर घुस जाते हैं।</li>\n            <li>यह वर्तमान स्थिति दर्शाती है कि शांति और जीवन की शक्ति अंततः हिंसा और हथियारों से सदा श्रेष्ठ सिद्ध होती है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बच्चों की घुड़सवारी व चिड़ियों के गपशप का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तोप के मुँह में चिड़ियों का प्रवेश (शांति की विजय)</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: ऐतिहासिक धरोहरों की प्रासंगिकता (Heritage Competency)</div>\n      <div class=\"cbq-question\">\n        \"धरोहरें हमें अपने इतिहास से जोड़ती हैं और भविष्य के लिए सचेत करती हैं।\" 'तोप' कविता के संदर्भ में इस कथन की सार्थकता सिद्ध कीजिए।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        कंपनी बाग में रखी तोप ईस्ट इंडिया कंपनी के आगमन और उनके दमनकारी शासन की ऐतिहासिक गवाह है। यह धरोहर हमें यह सिखाती है कि हमने आजादी कितने भारी बलिदानों से पाई है, ताकि हम भविष्य में कभी ऐसी भूल न करें जिससे देश की स्वतंत्रता पर पुनः कोई संकट आए। साथ ही यह तानाशाहों को चेतावनी भी देती है कि हथियारों के बल पर कोई शासन सदा नहीं टिकता।\n      </div>\n    </div>\n  </div>\n</section>","28":"<section class=\"chapter-section\" id=\"ch28\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">28</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 6</div>\n      <h2>कर चले हम फ़िदा</h2>\n      <p>कैफ़ी आज़मी | देशभक्ति गीत (फिल्म 'हकीकत', 1962 भारत-चीन युद्ध) — अमर बलिदान, राष्ट्र रक्षा की शपथ और युवाओं को संदेश | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch28-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">'सर हिमालय का हमने न झुकने दिया'—इस पंक्ति में हिमालय किस बात का प्रतीक है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>हिमालय भारत के गौरव, मान-सम्मान, संप्रभुता और राष्ट्रीय स्वाभिमान का सर्वोच्च प्रतीक है। सैनिकों ने अपने प्राणों का बलिदान देकर और खून बहाकर भी बर्फीली चोटियों पर शत्रु को आगे नहीं बढ़ने दिया और भारत माता के मस्तक (हिमालय) को कभी झुकने नहीं दिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हिमालय को राष्ट्रीय मान-सम्मान व संप्रभुता का प्रतीक बताना</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्राण देकर भी भारत के मस्तक की रक्षा करने का भाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch28-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">गीत में 'धरती को दुल्हन' क्यों कहा गया है?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>भारतीय संस्कृति में दुल्हन को लाल जोड़े में सजाया जाता है और उसकी मर्यादा व सम्मान की रक्षा करना दूल्हे का परम धर्म होता है।</p>\n          <p>सैनिकों ने युद्धभूमि में अपने लहू (रक्त) से भारत भूमि को लाल रंग से सराबोर कर दिया है मानो धरती ने लाल जोड़ा पहन लिया हो। जिस प्रकार एक सच्चा वीर अपनी दुल्हन के सम्मान पर कोई आँच नहीं आने देता, उसी प्रकार सैनिकों ने अपने प्राण देकर इस पावन धरती रूपी दुल्हन की अस्मिता की रक्षा की है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रक्त द्वारा धरती के लाल होने (लाल जोड़ा) का रूपक</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दुल्हन की तरह मातृभूमि की मर्यादा रक्षा का संकल्प</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch28-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">'खींच दो अपने खूँ से ज़मीं पर लकीर, इस तरफ़ आने पाए न रावण कोई'—पंक्ति का भावार्थ स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>भावार्थ:</strong> यहाँ कवि ने रामायण के 'लक्ष्मण रेखा' और 'रावण' के पौराणिक संदर्भों का सशक्त प्रतीकात्मक प्रयोग किया है:</p>\n          <ul>\n            <li>सैनिक देश के नवयुवकों से आह्वान करते हैं कि वे सीमाओं पर अपने बलिदान के रक्त से ऐसी अभेद्य रक्षा-रेखा खींच दें, जिसे पार करने की हिम्मत किसी शत्रु में न हो।</li>\n            <li>यहाँ 'रावण' देश पर बुरी नजर रखने वाले विदेशी आक्रांताओं (शत्रुओं) का प्रतीक है और 'सीता' भारत माता की प्रतीक है। यदि कोई भी विदेशी रावण भारत माता की ओर हाथ बढ़ाए, तो उसके हाथ काट दिए जाएँ।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लक्ष्मण रेखा और रावण के प्रतीकात्मक अर्थ का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मातृभूमि की अखंडता व शत्रु विनाश की प्रतिज्ञा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: नागरिक उत्तरदायित्व (Civic Competency)</div>\n      <div class=\"cbq-question\">\n        \"अब तुम्हारे हवाले वतन साथियो\" गीत केवल सीमा पर खड़े सैनिकों के लिए ही नहीं, बल्कि देश के प्रत्येक नागरिक के लिए एक संदेश है। स्पष्ट कीजिए कि शांति काल में आम नागरिक इस गीत की भावना को कैसे चरितार्थ कर सकते हैं?\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        देशभक्ति केवल सीमा पर गोली खाने तक सीमित नहीं है। शांति काल में नागरिक निम्नलिखित कार्यों से इस भावना को चरितार्थ कर सकते हैं:<br>\n        1. संविधान और कानूनों का निष्ठापूर्वक पालन करना।<br>\n        2. भ्रष्टाचार, सांप्रदायिकता और सामाजिक बुराइयों के विरुद्ध लड़ना।<br>\n        3. राष्ट्रीय संपत्ति की रक्षा करना और देश के आर्थिक विकास में ईमानदारी से श्रम करना। देश को सशक्त बनाना ही शहीदों को सच्ची श्रद्धांजलि है।\n      </div>\n    </div>\n  </div>\n</section>","29":"<section class=\"chapter-section\" id=\"ch29\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">29</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-2 (काव्य खंड) — पाठ 7</div>\n      <h2>आत्मत्राण</h2>\n      <p>गुरुदेव रवींद्रनाथ ठाकुर (अनुवाद: आचार्य हजारी प्रसाद द्विवेदी) | प्रार्थना गीत — आत्मबल, स्वावलंबन, संकटों पर विजय और अडिग ईश्वर-विश्वास | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch29-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch29-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कवि ईश्वर से विपदाओं से मुक्ति की प्रार्थना क्यों नहीं करता?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>कवि अन्य पारंपरिक भक्तों की तरह ईश्वर से दुख-दर्द, बीमारी या संकटों को दूर करने की भीख नहीं माँगता। वह एक स्वाभिमानी, कर्मठ और साहसी मनुष्य की तरह जीवन की चुनौतियों का सामना करना चाहता है।</p>\n          <p>कवि केवल यह प्रार्थना करता है कि संकट के समय उसका आत्मबल कभी न टूटे, वह भयभीत न हो और अपने पौरुष व शक्ति के बल पर हर आपदा पर विजय प्राप्त कर सके। वह ईश्वर पर बोझ नहीं बनना चाहता।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पारंपरिक याचना से भिन्न स्वाभिमानी दृष्टिकोण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विपदाओं पर स्वयं विजय पाने के आत्मबल की माँग</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch29-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch29-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">'आत्मत्राण' शीर्षक का अर्थ स्पष्ट कीजिए। यह कविता सामान्य प्रार्थना गीतों से किस प्रकार भिन्न है?</div>\n      <div class=\"q-marks\">4 अंक (80-100 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>'आत्मत्राण' का अर्थ:</strong> 'आत्म' का अर्थ है स्वयं और 'त्राण' का अर्थ है रक्षा या मुक्ति। अर्थात 'अपनी रक्षा स्वयं करना' अथवा 'आत्म-रक्षा का संकल्प'।</p>\n          <p><strong>सामान्य प्रार्थना गीतों से भिन्नता:</strong></p>\n          <ul>\n            <li><strong>याचनाहीन प्रार्थना:</strong> सामान्य प्रार्थना गीतों में भक्त ईश्वर से धन, सुख, स्वास्थ्य और संकटों से छुटकारा पाने की गुहार लगाता है। किंतु 'आत्मत्राण' में कवि किसी सांसारिक सुख या सांत्वना की याचना नहीं करता।</li>\n            <li><strong>पौरुष और संघर्ष की प्रेरणा:</strong> कवि दुख को जीवन की स्वाभाविक परीक्षा मानकर उससे जूझने की आंतरिक शक्ति माँगता है।</li>\n            <li><strong>अडिग निष्ठा:</strong> कवि कहता है कि जब संसार के सभी लोग मुझे धोखा दे दें और कोई सहायता न मिले, तब भी मेरा मन आपके प्रति संशय से न भरे। यह सर्वोच्च आत्मिक दृढ़ता का गीत है।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'आत्मत्राण' शब्द की सटीक व्युत्पत्ति व अर्थ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामान्य याचना गीतों और इस कविता के आत्मबल में अंतर</span><span class=\"marking-marks\">2.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: अभिकथन और कारण (Assertion &amp; Reason)</div>\n      <div class=\"cbq-question\">\n        <strong>अभिकथन (A):</strong> सुख के दिनों में भी कवि ईश्वर के प्रति कृतज्ञ बने रहना चाहता है।<br>\n        <strong>कारण (R):</strong> प्रायः मनुष्य दुख में भगवान को याद करता है और सुख में भूल जाता है, किंतु कवि सुख के हर पल में ईश्वर का पावन मुख पहचानना चाहता है।<br>\n        <strong>विकल्प:</strong><br>\n        (क) (A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।<br>\n        (ख) (A) और (R) दोनों सही हैं, परंतु (R), (A) की सही व्याख्या नहीं करता।<br>\n        (ग) (A) सही है, परंतु (R) गलत है।<br>\n        (घ) (A) गलत है, परंतु (R) सही है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>सही उत्तर: (क)</strong><br>\n        <em>व्याख्या:</em> कवि कहता है—<em>\"नतशिर होकर सुख के दिन में, तब मुख पहचानूँ छिन-छिन में।\"</em> वह सुख में भी ईश्वर-विस्मृति के दोष से बचना चाहता है, अतः (R) बिल्कुल सही व्याख्या करता है।\n      </div>\n    </div>\n  </div>\n</section>","30":"<section class=\"chapter-section\" id=\"ch30\" data-book=\"sanchayan\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">30</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">संचयन भाग-2 — पाठ 1</div>\n      <h2>हरिहर काका</h2>\n      <p>मिथिलेश्वर | मर्मस्पर्शी यथार्थवादी कहानी — पारिवारिक स्वार्थ, धर्म के ठेकेदारों का पाखंड, बुजुर्गों की उपेक्षा और संपत्ति का लोभ | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch30-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">अनपढ़ होते हुए भी हरिहर काका दुनिया की बेहतर समझ कैसे रखते हैं? कहानी के आधार पर स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>हरिहर काका भले ही औपचारिक रूप से पढ़े-लिखे नहीं थे, किंतु जीवन के कड़वे अनुभवों ने उन्हें दुनियादारी और इंसानी फितरत की गहरी समझ दी थी:</p>\n          <ul>\n            <li>वे भली-भाँति जानते थे कि उनके सगे भाई और ठाकुरबारी के महंत उनके प्रति जो थोड़ा-बहुत आदर या सेवा दिखा रहे हैं, वह उनके प्रति प्रेम के कारण नहीं, बल्कि उनकी 15 बीघे उपजाऊ जमीन के कारण है।</li>\n            <li>उन्होंने अपने गाँव में ऐसे कई बुजुर्गों को देखा था जिन्होंने जीते जी अपनी संपत्ति अपने परिजनों के नाम लिख दी थी और बाद में उन्हें कुत्ते की मौत मरना पड़ा था, कोई एक रोटी देने वाला भी नहीं बचा था।</li>\n            <li>इसलिए उन्होंने दृढ़ निश्चय किया कि जीते जी वे अपनी जमीन किसी के नाम नहीं लिखेंगे, चाहे भाई मार डालें या महंत जान से खत्म कर दें।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">15 बीघे जमीन के लोभ को पहचानने की क्षमता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गाँव के उपेक्षित वृद्धों के दृष्टांत से सीख व दृढ़ निर्णय</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch30-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">हरिहर काका को महंत और अपने भाई एक ही श्रेणी के क्यों लगने लगे?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>शुरू में हरिहर काका को लगता था कि भाई तो स्वार्थी हैं किंतु महंत जी भगवान के सच्चे सेवक हैं। किंतु बाद की घटनाओं ने सिद्ध कर दिया कि दोनों पक्षों में लेशमात्र भी अंतर नहीं था:</p>\n          <ul>\n            <li><strong>महंत का घिनौना रूप:</strong> महंत ने धर्म की आड़ में काका का अपहरण करवाया, उनके मुँह में कपड़ा ठूँसा, हाथ-पैर बाँधे और बंदूक की नोक पर जबरन सादे कागजों पर अँगूठे के निशान लगवाए।</li>\n            <li><strong>भाइयों की क्रूरता:</strong> भाइयों ने भी जब देखा कि काका जमीन नहीं लिख रहे, तो उन्होंने भी घर में काका को मारा-पीटा, जान से मारने की धमकी दी और जबरन अँगूठे लगवाए।</li>\n          </ul>\n          <p>दोनों का एकमात्र लक्ष्य काका की संपत्ति हड़पना था। रिश्ते और धर्म दोनों ही काका के लिए केवल स्वार्थ की चादर साबित हुए, इसलिए वे दोनों को एक ही थैली के चट्टे-बट्टे और हिंसक भेड़िया मानते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">महंत द्वारा अपहरण व अँगूठा लगवाने की हिंसा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाइयों द्वारा मारपीट व जमीन हड़पने की स्वार्थपरता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch30-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">कहानी के आधार पर स्पष्ट कीजिए कि पारिवारिक संबंधों में स्वार्थ और लोभ किस प्रकार जहर घोल रहा है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>'हरिहर काका' कहानी आज के आधुनिक समाज और टूटते पारिवारिक मूल्यों का वीभत्स यथार्थ प्रस्तुत करती है। खून के रिश्ते, जो कभी प्रेम, त्याग और सुरक्षा के आधार हुआ करते थे, आज केवल धन और जमीन-जायदाद के तराजू पर तौले जा रहे हैं।</p>\n          <p>भाइयों की पत्नियाँ काका को बचा-खुचा बासी भोजन देती हैं और जब जमीन हाथ से निकलती दिखती है, तो सगे भाई कसाई बन जाते हैं। यह कहानी दर्शाती है कि जहाँ अर्थ-लिप्सा (धन का लोभ) हावी हो जाती है, वहाँ दया, संवेदना और रिश्तों की पवित्रता का दम घुट जाता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रक्त-संबंधों में धनलोभ के कारण आई गिरावट का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पारिवारिक उपेक्षा व संवेदनहीनता का समाजशास्त्रीय निष्कर्ष</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: केस-आधारित सामाजिक चेतना (Competency Question)</div>\n      <div class=\"cbq-question\">\n        कहानी के अंत में हरिहर काका का मौन समाज के किस खोखलेपन पर गहरा प्रहार करता है? एक वृद्ध के रूप में उनकी अंतर्वेदना को स्पष्ट कीजिए।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        काका का मौन कोई साधारण चुप्पी नहीं, बल्कि समस्त मानवीय व्यवस्था, धर्म और रिश्तों के प्रति उनका अगाध तिरस्कार और विरक्ति है। वे अब किसी से कोई बात नहीं करते, केवल शून्य में ताकते रहते हैं। पुलिस के पहरे में जी रहे काका यह दर्शाते हैं कि संपत्ति होते हुए भी आज का वृद्ध कितना अकेला, असुरक्षित और मानसिक रूप से मृतप्राय हो चुका है। उनका मौन समूचे स्वार्थी समाज के गाल पर एक जोरदार तमाचा है।\n      </div>\n    </div>\n  </div>\n</section>","31":"<section class=\"chapter-section\" id=\"ch31\" data-book=\"sanchayan\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">31</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">संचयन भाग-2 — पाठ 2</div>\n      <h2>सपनों के-से दिन</h2>\n      <p>गुरदयाल सिंह | आत्मकथात्मक संस्मरण — बचपन की अल्हड़ स्मृतियाँ, स्कूल का भय, पीटी मास्टर प्रीतम चंद और हेडमास्टर शर्मा जी | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch31-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch31-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">पीटी मास्टर प्रीतम चंद की छवि कैसी थी और हेडमास्टर मदन मोहन शर्मा जी उनके विपरीत कैसे थे?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>दोनों शिक्षकों के व्यक्तित्व में जमीन-आसमान का अंतर था:</p>\n          <ul>\n            <li><strong>पीटी मास्टर प्रीतम चंद:</strong> ठिगने कद, दुबले-पतले शरीर, चीते जैसी आँखों वाले अत्यंत क्रूर और भयानक अध्यापक थे। वे बात-बात पर बच्चों की खाल खींच लेते थे (क्रूर पिटाई करते थे)। बच्चे उनसे थर-थर काँपते थे और सपने में भी उनके बूटों की आवाज से डरते थे।</li>\n            <li><strong>हेडमास्टर मदन मोहन शर्मा जी:</strong> वे अत्यंत सौम्य, शांत, दयालु और सहृदय व्यक्ति थे। उन्होंने कभी किसी बच्चे को छड़ी से नहीं पीटा था। वे हमेशा मीठी जुबान में समझाते थे और बच्चों से अगाध स्नेह रखते थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पीटी प्रीतम चंद के कठोर, हिंसक व डरावने रूप का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हेडमास्टर शर्मा जी की सौम्यता, स्नेह व अहिंसक व्यवहार</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch31-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch31-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">पीटी साहब को निलंबित (सस्पेंड) क्यों कर दिया गया था?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>एक दिन कक्षा चार में फारसी पढ़ाते समय बच्चों को शब्द-रूप याद नहीं थे। क्रोधित होकर मास्टर प्रीतम चंद ने सभी बच्चों को कान पकड़वाकर पीठ ऊँची कराकर 'मुर्गा' बना दिया। बच्चे धूप और दर्द से काँपने लगे और गिरने लगे।</p>\n          <p>उसी समय हेडमास्टर शर्मा जी वहाँ से गुजरे। नन्हें बच्चों की ऐसी अमानवीय और क्रूर सजा देखकर वे क्रोध से लाल हो गए। उन्होंने चिल्लाकर कहा—<em>\"व्हाट आर यू डूइंग? इज इट द वे टू पनिश स्टूडेंट्स?\"</em> उन्होंने तुरंत रियासत के शिक्षा विभाग को लिखकर प्रीतम चंद को नौकरी से मुअत्तल (सस्पेंड) कर दिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">फारसी याद न होने पर बच्चों को मुर्गा बनाने की अमानवीय सजा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हेडमास्टर शर्मा जी का हस्तक्षेप और तुरंत निलंबन की कार्रवाई</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch31-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch31-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">हेडमास्टर शर्मा जी के कमरे में प्रीतम चंद को तोतों को बादाम खिलाते देखकर बच्चों को कैसा आश्चर्य हुआ?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>निलंबन के दौरान जब बच्चे प्रीतम चंद के कमरे पर कागज़ पहुँचाने गए, तो उन्होंने देखा कि जिस जल्लाद जैसे मास्टर से पूरा स्कूल काँपता था, वह पिंजरे में बंद तोतों से मीठी-मीठी बातें कर रहा था और उन्हें अपने हाथों से छिले हुए बादाम खिला रहा था। बच्चों के लिए यह दृश्य किसी अजूबे से कम नहीं था कि ऐसे कठोर और निर्दयी इंसान के सीने में भी कहीं कोमल भावनाएँ हो सकती हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तोतों से मीठी बातें करने व बादाम खिलाने का आश्चर्य</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">क्रूर शिक्षक के भीतर छिपे कोमल भाव पर बाल-विस्मय</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: आधुनिक बाल-शिक्षा बनाम शारीरिक दंड (Educational Competency)</div>\n      <div class=\"cbq-question\">\n        वर्तमान शिक्षा व्यवस्था में 'शारीरिक दंड' (कॉर्पोरल पनिशमेंट) को कानूनन प्रतिबंधित क्यों किया गया है? पाठ के आधार पर स्पष्ट कीजिए कि भय और प्रेम में से कौन-सा माध्यम सीखने के लिए अधिक प्रभावी है।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        शारीरिक दंड से बच्चे के मन में विद्यालय, शिक्षकों और पढ़ाई के प्रति स्थायी भय, हीनभावना और घृणा उत्पन्न हो जाती है (जैसा कि लेखक और उनके साथियों को स्कूल किसी यातनागृह जैसा लगता था)। भय से केवल अनुशासन का ढोंग कराया जा सकता है, ज्ञान का विकास नहीं। प्रेम, सहानुभूति और प्रेरणा (जैसा हेडमास्टर शर्मा जी का व्यवहार था) ही बच्चे की स्वाभाविक रचनात्मकता और सीखने की जिज्ञासा को जाग्रत करती है।\n      </div>\n    </div>\n  </div>\n</section>","32":"<section class=\"chapter-section\" id=\"ch32\" data-book=\"sanchayan\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">32</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">संचयन भाग-2 — पाठ 3</div>\n      <h2>टोपी शुक्ला</h2>\n      <p>डॉ. राही मासूम रज़ा | उपन्यास अंश — सांप्रदायिक सीमाओं से परे बाल-मित्रता, अपनत्व की तलाश, दादी का स्नेह और पारिवारिक एकाकीपन | CBSE Board 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">पाठ्यपुस्तक के अभ्यास प्रश्न-उत्तर (NCERT Textbook Solutions)</div>\n\n  <div class=\"q-card\" id=\"ch32-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch32-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">इफ़्फ़न और टोपी शुक्ला की मित्रता किन बातों पर आधारित थी? दोनों के पारिवारिक परिवेश में क्या भिन्नता थी?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>मित्रता का आधार:</strong> टोपी (हिंदू ब्राह्मण) और इफ़्फ़न (मुस्लिम) की मित्रता धर्म या मजहब की दीवारों से ऊपर उठकर भावनात्मक अपनत्व, सादगी और निश्छल बाल-प्रेम पर टिकी थी। टोपी को अपने घर में जो ममता और प्यार नहीं मिलता था, वह उसे इफ़्फ़न की दादी की गोद में मिलता था।</p>\n          <p><strong>पारिवारिक भिन्नता:</strong></p>\n          <ul>\n            <li>टोपी का परिवार कट्टर कर्मकांडी हिंदू ब्राह्मण परिवार था, जहाँ पिता डॉक्टर थे और दादी अत्यंत सख्त और डाँटने वाली थीं।</li>\n            <li>इफ़्फ़न का परिवार सैयद मुस्लिम परिवार था, जहाँ पिता कलेक्टर थे और घर में मुहर्रम की परंपराएँ थीं। दोनों परिवारों के रीति-रिवाज बिल्कुल विपरीत थे।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भावनात्मक अपनत्व व निश्छल मित्रता का आधार</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हिंदू-मुस्लिम पारिवारिक पृष्ठभूमि व संस्कारों का अंतर</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch32-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch32-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">टोपी ने इफ़्फ़न की दादी के देहांत पर ऐसा क्यों कहा कि \"काश! तेरी दादी की जगह मेरी दादी मर जाती\"?</div>\n      <div class=\"q-marks\">3 अंक (40-50 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>टोपी का यह कथन किसी दुर्भावना से नहीं, बल्कि उसकी गहरी बाल-सुलभ वेदना और अपनत्व की तड़प से निकला था:</p>\n          <ul>\n            <li>टोपी की अपनी दादी सुभद्रा देवी अत्यंत कठोर, डाँटने-फटकारने वाली और भेदभाव करने वाली महिला थीं, जिनसे टोपी को कभी प्यार नहीं मिला।</li>\n            <li>दूसरी ओर, इफ़्फ़न की दादी पूरबिया बोली में टोपी को प्यार से पुचकारती थीं, कहानियाँ सुनाती थीं और उसे असीम वात्सल्य देती थीं।</li>\n            <li>इफ़्फ़न की दादी की मृत्यु के साथ टोपी का एकमात्र सच्चा ममता-स्रोत छिन गया और वह बिल्कुल अकेला पड़ गया। इसलिए दुख के अतिरेक में उसने यह बात कही।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अपनी दादी के रूखेपन व इफ़्फ़न की दादी के अगाध वात्सल्य का अंतर</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ममता के छिन जाने पर उपजे एकाकीपन की अभिव्यक्ति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"ch32-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch32-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">नौवीं कक्षा में दो बार फेल होने पर टोपी को किन-किन मानसिक यातनाओं और उपहास का सामना करना पड़ा?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Board Standard Solution</div>\n        <div class=\"answer-text\">\n          <p>टोपी नौवीं कक्षा में अपनी किसी लापरवाही के कारण नहीं, बल्कि घर के कामों और टाइफाइड बीमारी के कारण फेल हुआ था। किंतु उसे घर और स्कूल दोनों जगह भीषण अपमान सहना पड़ा:</p>\n          <ul>\n            <li><strong>घर में उपहास:</strong> घर वाले उसे हर बात पर ताना मारते थे। चाय की एक प्याली तक के लिए उसकी योग्यता पर सवाल उठाए जाते थे।</li>\n            <li><strong>स्कूल में साथियों का बिछोह:</strong> उसके पुराने साथी दसवीं में चले गए और वह अपने से छोटे लड़कों के बीच बैठने पर मजबूर हुआ। वे लड़के उस पर फब्तियाँ कसते थे।</li>\n            <li><strong>शिक्षकों की उपेक्षा:</strong> मास्टर साहब भी कमजोर लड़कों को समझाते हुए टोपी का नाम लेकर कहते थे—\"अगर नहीं पढ़ोगे तो बलभद्र नारायण (टोपी) की तरह इसी क्लास में सड़ते रहोगे।\" इस अपमान ने उसके बाल-मन को भीतर तक छलनी कर दिया।</li>\n          </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Board Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घर में तानों और हीन व्यवहार का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्कूल में नए लड़कों व मास्टरों के उपहास का मार्मिक विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <div class=\"cbq-badge\">CBSE CBQs</div>\n      <h3>योग्यता-आधारित उच्च स्तरीय प्रश्न (Competency-Based Questions)</h3>\n    </div>\n    <div class=\"cbq-card\">\n      <div class=\"cbq-type\">CBQ 1: सांस्कृतिक समन्वय और भाषा (Cultural Competency)</div>\n      <div class=\"cbq-question\">\n        'टोपी शुक्ला' कहानी यह सिद्ध करती है कि मानवीय भावनाएँ और अपनत्व किसी धर्म या भाषा की परिधि में नहीं बँधते। इस कथन के समर्थन में तर्क प्रस्तुत कीजिए।\n      </div>\n      <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें</button>\n      <div class=\"cbq-answer\">\n        <strong>उत्तर:</strong><br>\n        टोपी हिंदू कट्टर परिवार का था, किंतु उसे सबसे अधिक सुख मुस्लिम परिवार की दादी की बोली और गोद में मिलता था। वह दादी के मुँह से 'पूरबी बोली' सुनकर तृप्त होता था और अपनी माँ को 'अम्मी' कहने लगा था। प्रेम की कोई भाषा या मजहब नहीं होता; जहाँ हृदय को सच्ची ममता, सम्मान और आत्मीयता मिलती है, आत्मा वहीं अपना घर बना लेती है। यह कहानी भारत की साझी संस्कृति का सबसे गहरा और मानवीय साक्ष्य है।\n      </div>\n    </div>\n  </div>\n</section>"};
